const top_cassiopeia = {
  champion: '카시오페아',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '(Q)\'맹독 폭발\'로 가렌을 중독시켜 이동 속도를 얻고 거리를 유지하세요. 가렌이 (Q)\'결정타\'로 달려와 침묵을 걸면 스킬을 쓸 수 없으니 무리하게 붙지 마세요. 가렌의 (P)\'인내심\' 회복이 시작되지 않도록 짧은 간격으로 계속 독을 묻히는 것이 중요해요.', lv3: '(Q)\'맹독 폭발\'로 중독시킨 뒤 (E)\'쌍독니\'를 연사해 체력을 회복하며 딜교환하세요. 가렌이 (Q)\'결정타\'로 둔화를 지우고 달려들기 전에 (W)\'독기의 늪\'으로 접근 경로를 방해하는 것이 좋아요. (W)\'용기\'의 보호막과 피해 감소가 켜진 동안에는 공격을 아꼈다가 효과가 끝난 뒤에 다시 압박하세요.', lv6: '가렌이 (E)\'심판\'으로 회전하며 다가올 때 (R)\'석화의 응시\'로 기절시켜 흐름을 끊어주세요. (R)\'데마시아의 정의\'는 체력이 낮을 때 치명적이니 자신의 체력이 적다면 무리하게 버티지 말고 빠르게 빠져야 해요. 라인을 당겨 두고 가렌이 진입할 때 (W)\'독기의 늪\'을 깔아 이동을 늦추고 정글러와 함께 대응하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 높은 가렌에게 지속 피해를 입히세요. 신발은 가렌의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (P)\'인내심\'의 체력 회복을 억제해야 킬각을 잡기 편해요.' },
    '갱플랭크': { lv1: '(Q)\'맹독 폭발\'로 먼저 독을 묻히고 (E)\'쌍독니\'로 체력을 회복하며 견제하세요. (Q)\'혀어어어업상\'은 대상을 지정해 쏘는 스킬이라 미니언 뒤에 숨어도 맞으니 무리하게 다가가지 마세요. (Q)\'맹독 폭발\' 적중 시 얻는 이동 속도로 상대의 거리에서 유연하게 움직이며 피해를 최소화해요.', lv3: '(E)\'화약통\'이 깔린 주변에서는 싸우지 말고 (W)\'독기의 늪\'을 사용해 갱플랭크의 움직임을 둔화시키세요. (W)\'괴혈병 치료\'로 군중 제어 효과를 지울 수 있으니, 이 스킬이 빠진 것을 확인한 뒤 (Q)\'맹독 폭발\'과 (E)\'쌍독니\' 연계로 딜교환을 이어 가세요. 상대가 (E)\'화약통\'을 설치하면 빠르게 자리를 옮겨 폭발 범위에서 벗어나야 해요.', lv6: '(R)\'포탄 세례\'가 떨어지는 위치를 피해 이동하며 (R)\'석화의 응시\'로 갱플랭크를 기절시키세요. 다만 (W)\'괴혈병 치료\'로 기절을 즉시 풀 수 있으니, 귤이 빠진 것을 확인한 뒤에 (R)\'석화의 응시\'를 써야 확실한 킬각을 잡을 수 있어요. 라인을 적당히 당겨서 (E)\'화약통\' 연쇄 폭발에 휘말리지 않도록 주의하며 정글러의 개입을 노리세요.', item: '판금 장화를 신어 갱플랭크의 기본 공격 피해를 줄이세요. 판금 장화는 (Q)\'혀어어어업상\' 같은 스킬 피해는 줄이지 못하니 스킬은 거리와 위치로 관리해요. 첫 코어로는 리안드리의 고통을 가서 체력을 보충하고 지속적인 마법 피해를 입히세요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (W)\'괴혈병 치료\'의 회복량을 깎아야 킬각을 잡기 편해요.' },
    '그라가스': { lv1: '(Q)\'술통 굴리기\'의 둔화와 견제를 조심하며 (Q)\'맹독 폭발\'로 독을 묻히고 이동 속도를 얻으세요. 술통이 굴러오는 경로를 피해 걷고, 독에 걸린 그라가스에게 (E)\'쌍독니\'를 섞어 체력을 유지하세요. (P)\'서비스 시간\'으로 인한 회복이 있으니 무리한 소모전보다는 거리 조절에 집중하세요.', lv3: '그라가스가 (E)\'몸통 박치기\'로 들어오기 전에 발밑에 (W)\'독기의 늪\'을 깔아 돌진을 쓰지 못하게 하고 둔화를 거세요. 그라가스가 (W)\'취중 분노\'를 켜서 피해 감소 효과를 얻었을 때는 (E)\'쌍독니\' 사용을 잠시 멈추는 것이 좋아요. (Q)\'맹독 폭발\'로 먼저 독을 묻힌 뒤 (W)\'독기의 늪\' 위에서 (E)\'쌍독니\'를 빠르게 연사해 딜교환을 이끄세요.', lv6: '그라가스가 (E)\'몸통 박치기\'로 진입할 때 (R)\'석화의 응시\'를 사용해 정면에서 기절시키세요. (R)\'술통 폭발\'에 밀려나면 딜교환 흐름이 끊기니 거리 조절에 유의하고 정글러의 개입을 조심하세요. 라인을 적절히 유지하며 (Q)\'맹독 폭발\'과 (E)\'쌍독니\'의 연계로 체력을 깎아 킬각을 잡으세요.', item: '리안드리의 고통을 가서 체력과 지속 피해로 그라가스의 유지력을 압도하세요. 신발은 마법 저항력을 높여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'의 체력 회복을 점화로 억제해야 처치가 편해요.' },
    '그웬': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'로 견제하며 이동 속도를 챙기세요. 그웬이 (Q)\'싹둑싹둑!\'을 쓰러 다가올 때 정면 중앙의 고정 피해를 피하며 거리를 벌려야 해요. 평타 교환을 길게 하면 (P)\'가위 난도질\' 회복 때문에 밀리니 짧게 치고 빠지세요.', lv3: '그웬이 (E)\'돌격가위\'로 진입하려 할 때 발밑에 (W)\'독기의 늪\'을 깔아 돌진을 막으세요. (Q)\'맹독 폭발\'로 중독시킨 뒤 (E)\'쌍독니\'를 계속 사용해 체력을 회복하며 딜교환하세요. (W)\'신성한 안개\'는 대상 지정 스킬만 막으므로 (Q)\'맹독 폭발\'과 (W)\'독기의 늪\'은 안개 속으로 그대로 넣을 수 있어요.', lv6: '그웬이 (R)\'바느질\'로 둔화를 걸며 다가오면 (R)\'석화의 응시\'로 정면에서 기절시켜 흐름을 끊으세요. 기절한 동안 (Q)\'맹독 폭발\'과 (E)\'쌍독니\'를 쏟아부어 빠르게 피해를 입히는 게 중요해요. 정글러가 개입할 때는 (W)\'독기의 늪\'으로 적의 진입 경로를 차단해 아군을 보호하세요.', item: '리안드리의 고통을 첫 코어로 선택해 지속 피해를 입히고 체력이 높은 그웬을 압박하세요. 신발은 마법 저항력을 높여 그웬의 마법 피해를 줄여 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'가위 난도질\'로 인한 그웬의 체력 회복을 점화로 억제해야 마무리하기 편해요.' },
    '나르': { lv1: '(Q)\'부메랑 던지기\'의 긴 사거리 때문에 초반에는 뒤로 물러나며 (Q)\'맹독 폭발\'로 체력을 깎으세요. 나르가 (W)\'슝슝\' 추가 피해를 입히려 다가오면 거리 조절을 하며 (E)\'쌍독니\'로 체력을 회복해 버티세요. 첫 웨이브에서는 무리하게 딜교환하기보다 미니언을 챙기며 기회를 보세요.', lv3: '나르가 (E)\'폴짝\'으로 진입하려고 할 때 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막고 둔화를 거세요. 중독된 나르에게 (E)\'쌍독니\'를 빠르게 연사해 강력한 피해를 입히는 구도를 만드세요. (Q)\'부메랑 던지기\'의 둔화에 걸리면 (Q)\'맹독 폭발\'로 자신의 이동 속도를 높여 거리 조절을 하세요.', lv6: '메가 나르가 (W)\'쿵쾅\'으로 기절시키려 할 때 (R)\'석화의 응시\'를 사용해 먼저 기절시키거나 둔화를 거세요. (R)\'나르!\'에 밀려 벽에 부딪히면 기절하므로 항상 벽에서 떨어진 위치를 잡고 싸우세요. 라인을 밀 때는 나르가 메가 나르 상태에서 (Q)\'돌덩이 던지기\'로 압박할 수 있으니 주의하며 정글러를 부르세요.', item: '판금 장화로 나르의 기본 공격 피해를 줄이세요. 리안드리의 고통을 올려 체력이 높은 메가 나르에게 지속적인 마법 피해를 입히세요.', spell: '점멸과 정화를 추천해요. 메가 나르의 (W)\'쿵쾅\' 기절을 정화로 빠르게 풀고 거리 조절을 할 수 있어요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\' 중첩을 쌓으려 하니 (Q)\'맹독 폭발\'로 끊임없이 견제해서 막타를 방해하세요. (Q)\'맹독 폭발\'로 이동 속도를 얻으며 거리를 유지하면 나서스가 다가오기 힘들어요. 평타 교환은 (P)\'영혼의 포식자\' 생명력 흡수 때문에 짧게 끝내세요.', lv3: '나서스가 (W)\'쇠약\'을 걸면 이동 속도가 느려지니 즉시 (W)\'독기의 늪\'을 깔아 맞대응하고 (E)\'쌍독니\'로 체력을 회복하며 버티세요. (E)\'영혼의 불길\' 장판 위에서는 방어력이 낮아지니 빠르게 벗어나야 해요. (Q)\'맹독 폭발\'을 먼저 맞히고 (E)\'쌍독니\'를 연사하는 리듬으로 딜교환을 이끌어 가세요.', lv6: '나서스가 (R)\'사막의 분노\'를 켜면 체력과 방어력이 늘어나니 무리하게 붙지 말고 거리를 벌려 시간을 버리세요. 나서스가 진입할 때 (R)\'석화의 응시\'로 기절시켜 멈춰 세우고 (E)\'쌍독니\'를 쏟아부어 딜교환을 하세요. 라인을 계속 밀어 나서스가 (Q)\'흡수의 일격\' 스택을 편하게 쌓지 못하게 방해하는 운영이 좋아요.', item: '리안드리의 고통으로 체력이 많은 나서스에게 지속적인 피해를 입히세요. 신발은 (Q)\'흡수의 일격\' 같은 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'영혼의 포식자\'의 회복량을 줄여 초반에 나서스를 압박하고 킬각을 잡기 좋아요.' },
    '녹턴': { lv1: '(Q)\'맹독 폭발\'을 사용하여 적을 중독시키고 이동 속도를 높여 거리를 유지하세요. 녹턴이 (Q)\'황혼의 인도자\'로 다가오려고 하면 무리하게 맞서기보다 뒤로 물러나며 웨이브를 관리해야 해요. 초반에는 적의 접근을 막으며 지속적인 피해를 주는 데 집중하세요.', lv3: '(Q)\'맹독 폭발\'로 적을 중독시킨 뒤 (E)\'쌍독니\'를 사용하여 강력한 피해와 체력 회복을 노리세요. 녹턴이 (W)\'어둠의 장막\'을 사용해 스킬을 막으려 할 수 있으니 스킬을 하나 먼저 써서 보호막을 빼내는 것이 좋아요. 만약 (E)\'말할 수 없는 공포\'에 걸릴 것 같다면 빠르게 범위를 벗어나 공포를 피하세요.', lv6: '녹턴이 (R)\'피해망상\'으로 날아올 때 정면으로 (R)\'석화의 응시\'를 사용하여 기절시키고 대응하세요. (W)\'독기의 늪\'을 미리 깔아두면 상대가 이동 스킬을 사용하여 접근하는 것을 방해할 수 있어요. 시야가 차단된 상태에서는 정글러의 개입을 경계하며 라인 관리에 신경 써야 해요.', item: '판금 장화와 내셔의 이빨을 추천해요. 판금 장화는 상대의 기본 공격 피해를 줄여주고 내셔의 이빨은 주문력과 공격 속도를 제공해요.', spell: '점멸과 정화를 선택하세요. 정화를 사용하여 (E)\'말할 수 없는 공포\'로 인한 공포 상태를 즉시 해제하고 생존할 수 있어요.' },
    '다리우스': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'로 지속적인 피해를 입히며 거리 조절을 하세요. 다리우스가 (Q)\'학살\'의 도끼날 끝에 맞히려고 다가오니, 그 범위 밖에서 견제하세요. 근접전이 길어지면 (P)\'과다출혈\' 중첩이 쌓여 위험하니 짧게 교환하고 빠지세요.', lv3: '(E)\'포획\'에 끌려가면 순식간에 (P)\'과다출혈\' 중첩이 쌓이니 거리 유지에 집중하세요. 다리우스가 접근할 때 (W)\'독기의 늪\'을 깔면 이동 속도를 늦춰 (E)\'포획\' 사거리 안으로 들어오기 어렵게 만들 수 있어요. (Q)\'맹독 폭발\'로 중독시킨 뒤 (E)\'쌍독니\'를 빠르게 사용해 체력을 회복하며 압박하세요.', lv6: '(E)\'포획\'에 끌려오면 공중에 떠서 스킬을 쓸 수 없으니 (R)\'석화의 응시\'는 끌어당기기 전에 다리우스가 정면으로 접근할 때 미리 쓰세요. (P)\'과다출혈\' 중첩이 쌓인 상태에서는 (R)\'녹서스의 단두대\' 피해가 매우 크니 무리하게 붙지 마세요. 라인 관리를 통해 정글러의 개입을 유도하고 포탑 근처에서 안전하게 견제하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력을 챙기고 지속적인 마법 피해를 입히세요. 신발은 기본 공격 피해를 줄여 주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. (Q)\'학살\'을 통한 다리우스의 체력 회복을 억제하고 킬각을 잡을 때 유용해요.' },
    '라이즈': { lv1: '라이즈의 (Q)\'과부하\'는 첫 번째로 맞은 적에게만 피해를 입히니 미니언 뒤에 서서 피해를 줄이세요. (Q)\'맹독 폭발\'을 사용해 라이즈의 체력을 깎고 이동 속도를 높여 거리 조절을 하세요. 초반에는 무리하게 붙기보다 견제 위주로 플레이하며 상대의 스킬 낭비를 유도하세요.', lv3: '(E)\'주문 전이\' 표식이 남은 상태에서 (W)\'룬 감옥\'에 맞으면 속박되니, 표식이 붙었을 때는 라이즈와 거리를 벌리세요. 라이즈가 스킬을 쏟아낸 뒤 (Q)\'맹독 폭발\'로 중독시키고 (E)\'쌍독니\'를 빠르게 연사해 체력을 회복하며 압박하세요. (W)\'독기의 늪\'을 깔아 라이즈의 움직임을 제한하고 (E)\'쌍독니\'의 피해를 극대화하세요.', lv6: '라이즈가 (R)\'공간 왜곡\'을 사용해 정글러를 부르거나 도망갈 수 있으니, 상대의 궁극기 사용 여부를 항상 확인하세요. 라이즈가 다가올 때 (R)\'석화의 응시\'로 기절시킨 뒤 (E)\'쌍독니\'를 쏟아부으면 빠르게 킬각을 잡을 수 있어요. 라인을 너무 깊게 밀면 속박 연계에 노출되어 정글러의 개입에 취약해지니 주의하세요.', item: '리안드리의 고통을 첫 코어로 선택해 지속 피해를 입히고 체력을 보충하세요. 신발은 마법 저항력을 높이고 속박과 둔화 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 라이즈의 끈질긴 견제를 버티며 라인 복귀와 합류전을 준비하는 것이 효율적이에요.' },
    '럼블': { lv1: '(Q)\'화염방사기\'의 원뿔 범위 밖에서 (Q)\'맹독 폭발\'로 견제하며 이동 속도를 높이세요. 럼블이 근접해서 태우려 하면 거리를 벌리며 (Q)\'맹독 폭발\'로 독만 묻히는 것이 중요해요.', lv3: '(E)\'전기 작살\'에 맞으면 둔화와 마법 저항력 감소가 걸리니 (W)\'독기의 늪\'을 깔아 거리 조절을 하세요. (W)\'고철 방패\'의 보호막이 사라진 시점에 (Q)\'맹독 폭발\'을 맞히고 (E)\'쌍독니\'를 연사해 체력을 회복하며 딜교환하세요.', lv6: '(R)\'이퀄라이저 미사일\'이 깔리면 즉시 범위 밖으로 벗어나고 장판 위에서 버티지 마세요. 럼블이 (Q)\'화염방사기\'로 붙으려 할 때 정면에서 (R)\'석화의 응시\'를 사용해 기절시키면 일방적인 공격이 가능해요. 라인을 밀 때는 (R)\'이퀄라이저 미사일\'과 정글러의 호응을 주의하며 거리를 유지하세요.', item: '리안드리의 고통을 첫 코어로 선택해 지속 피해와 체력을 챙기세요. 신발은 (E)\'전기 작살\'과 (R)\'이퀄라이저 미사일\'의 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 적합해요.', spell: '점멸과 점화를 추천해요. 럼블은 (W)\'고철 방패\'로 피해를 흡수하니 보호막이 빠진 뒤에 점화의 지속 고정 피해로 마무리하세요.' },
    '레넥톤': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'로 레넥톤을 중독시키고 이동 속도를 얻어 거리를 벌리세요. 레넥톤이 (Q)\'양떼 도륙\'으로 접근해 체력을 회복하려 할 때 사거리 밖에서 평타와 (E)\'쌍독니\'를 섞어 견제해요. 무리하게 붙기보다 미니언 뒤에서 짧게 딜교환을 하며 체력을 유지하세요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 진입할 때 발밑에 (W)\'독기의 늪\'을 깔아 이동 스킬 재사용을 막으세요. (W)\'무자비한 포식자\'의 기절을 맞으면 (E)\'쌍독니\'를 쓰지 못하니 기절이 빠진 뒤에 딜교환을 시작해요. 중독된 상태에서 (E)\'쌍독니\'를 계속 사용해 레넥톤의 체력 회복량을 압도하세요.', lv6: '(R)\'강신\'을 켜고 들어오는 레넥톤을 향해 (R)\'석화의 응시\'를 사용해 기절시켜 진입을 차단하세요. 기절한 동안 (Q)\'맹독 폭발\'과 (E)\'쌍독니\'를 쏟아부어 빠르게 체력을 깎는 것이 중요해요. 레넥톤의 분노가 높을 때는 (W)\'무자비한 포식자\' 기절 시간이 길어지니 정면 충돌을 피하고 라인을 당겨 정글의 도움을 받으세요.', item: '리안드리의 고통을 첫 코어로 가서 체력을 보충하고 지속 피해를 입히세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (Q)\'양떼 도륙\'의 체력 회복량을 줄여야 딜교환에서 앞설 수 있어요.' },
    '렝가': { lv1: '렝가가 수풀에서 (P)\'보이지 않는 포식자\'로 도약하지 못하게 거리를 유지하며 (Q)\'맹독 폭발\'로 먼저 독을 묻혀요. 상대가 다가오려 하면 최대한 뒤로 물러나며 견제에 집중하세요.', lv3: '렝가가 (E)\'올가미 투척\'을 맞춘 후 들어온다면 발밑에 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 방해하세요. 중독된 상태의 적에게 (E)\'쌍독니\'를 사용하여 피해를 입히고 체력을 회복해요.', lv6: '렝가가 (R)\'사냥의 전율\'을 사용하여 위장 상태로 접근할 때 정면에서 (R)\'석화의 응시\'를 맞춰 기절시켜요. 라인을 관리하여 렝가가 수풀을 이용하기 어렵게 만들고 정글러의 개입에 대비하세요.', item: '판금 장화와 리안드리의 고통을 구매해요. 판금 장화는 렝가의 기본 공격 피해를 줄여주고 리안드리의 고통은 지속 피해를 입히는 데 도움을 줘요.', spell: '점멸과 탈진을 선택해요. 점멸로 위치를 변경하여 생존하고 탈진으로 렝가의 피해량을 감소시켜요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 활용한 돌진과 (P)\'룬 검\'의 추가 피해로 초반 교환이 매우 강해요. 1~2레벨에는 (Q)\'맹독 폭발\'로 리븐의 체력을 미리 깎으며 거리를 유지하세요. 리븐이 (Q)\'부러진 날개\'로 파고들려고 하면 평타와 스킬로 대응하며 거리를 벌려야 해요.', lv3: '리븐이 (W)\'기 폭발\'로 기절을 시키면 대응하기 어려우니 스킬이 빠지기 전까지는 주의하세요. 리븐이 (Q)\'부러진 날개\'나 (E)\'용맹\'으로 진입할 때 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막는 것이 중요해요. 리븐이 독에 중독된 상태라면 (E)\'쌍독니\'를 사용하여 피해를 입히고 체력을 회복하세요.', lv6: '리븐이 (R)\'추방자의 검\'을 사용해 사거리가 길어지면 무리하게 맞붙지 말고 거리를 조절하세요. 리븐이 돌진해 들어오는 순간 (R)\'석화의 응시\'를 사용하여 기절을 시키면 킬각을 잡기 쉬워요. 리븐의 (E)\'용맹\' 보호막이 빠진 타이밍에 (W)\'독기의 늪\'을 활용해 압박하세요.', item: '첫 코어 아이템으로 내셔의 이빨을 선택해 공격 속도와 주문력을 챙기세요. 신발은 리븐의 (P)\'룬 검\'이 실린 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 탈진을 추천해요. 리븐이 (E)\'용맹\'과 함께 들어올 때 탈진을 사용하면 피해량을 줄여 위기를 넘길 수 있어요.' },
    '리산드라': { lv1: '리산드라가 (Q)\'얼음 파편\'으로 미니언을 관통하며 견제하니 미니언 뒤에 있지 말고 옆으로 비켜서서 피해를 최소화하세요. 1~2레벨에는 (Q)\'맹독 폭발\'을 적중시켜 독을 묻힌 뒤 (E)\'쌍독니\'로 체력을 회복하며 거리 조절을 하세요.', lv3: '리산드라가 (E)\'얼음갈퀴 길\'을 사용하여 순간이동으로 들어올 때 (W)\'독기의 늪\'을 깔아 이동 스킬을 못 쓰게 만드세요. 리산드라의 (W)\'서릿발\'에 묶이더라도 (E)\'쌍독니\'를 사용하여 독에 중독된 대상에게 높은 피해를 입히세요. (Q)\'얼음 파편\'이 날아오는 것을 보고 (Q)\'맹독 폭발\'을 맞춰 거리를 조절하는 것도 중요해요.', lv6: '리산드라가 자신에게 (R)\'얼음 무덤\'을 사용하여 무적 상태가 된다면 잠시 공격을 멈추고 다음 기회를 기다리세요. 리산드라의 (R)\'얼음 무덤\' 기절을 맞기 전에 (R)\'석화의 응시\'를 사용하거나 기절한 뒤에는 정화로 빠르게 풀어내야 해요. 리산드라가 (E)\'얼음갈퀴 길\'로 들어오는 위치에 (W)\'독기의 늪\'을 배치하며 라인을 관리하세요.', item: '첫 코어로 리안드리의 고통을 선택하여 지속적인 마법 피해를 입히세요. 신발은 리산드라의 마법 피해를 줄이고 (W)\'서릿발\'과 (R)\'얼음 무덤\'의 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. 리산드라의 (R)\'얼음 무덤\' 기절은 정화로 풀 수 있으며 (W)\'서릿발\'의 속박도 정화로 해결할 수 있어요.' },
    '마스터이': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'로 마스터 이를 중독시키고 (E)\'쌍독니\'로 계속해서 체력을 깎아내세요. (Q)\'일격 필살\'은 대상으로 지정할 수 없는 상태로 순간이동하므로 예측해서 피하기보다 거리를 두고 견제하는 것이 좋아요.', lv3: '마스터 이가 (W)\'명상\'을 켜면 피해량이 감소하고 체력을 회복하니 딜교환을 잠시 멈추고 기다리세요. (W)\'독기의 늪\'을 발밑에 깔아 둔화시키고 (E)\'쌍독니\'를 빠르게 연사해 (E)\'우주류 검술\'의 고정 피해를 입기 전에 압박하세요. (Q)\'일격 필살\'이 빠진 시점이 가장 안전하게 공격할 수 있는 기회예요.', lv6: '(R)\'최후의 전사\'를 켜면 둔화에 면역이 되어 (W)\'독기의 늪\'의 느려짐 효과가 통하지 않으니 (R)\'석화의 응시\'로 기절시키는 것이 중요해요. 마스터 이가 정면에서 달려들 때 (R)\'석화의 응시\'를 써서 멈춰 세운 뒤 (E)\'쌍독니\'로 빠르게 폭딜을 넣으세요. 정글러가 개입할 때 (R)\'최후의 전사\'의 지속시간이 늘어나지 않도록 빠르게 처리해야 해요.', item: '리안드리의 고통을 첫 코어로 가서 지속적인 마법 피해를 입히세요. 신발은 마스터 이의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복하는 것을 방해하고 확실하게 마무리하기 위해 점화가 필요해요.' },
    '마오카이': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'을 적중시켜 중독시킨 뒤 (E)\'쌍독니\'로 피해를 입히며 거리를 조절하세요. 마오카이가 (Q)\'덤불 주먹\'으로 밀어내며 접근할 때 거리를 유지하며 계속해서 견제하는 것이 중요해요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'을 쓰기 전에 발밑에 (W)\'독기의 늪\'을 깔면 이동 스킬을 쓰지 못하게 막을 수 있어요. (Q)\'맹독 폭발\'로 중독된 상태에서 (E)\'쌍독니\'를 맞히면 더 많은 피해를 주고 체력도 회복할 수 있어요. (E)\'묘목 던지기\'가 수풀에 깔려 있다면 그 근처에서의 교환은 피하세요.', lv6: '마오카이가 (R)\'대자연의 마수\'로 벽을 세우며 다가오면 벽의 진행 방향 옆으로 피해 속박을 피하세요. 마오카이가 정면에 보일 때 (R)\'석화의 응시\'를 사용해 기절시키면 킬을 노릴 수 있어요. 마오카이의 궁극기로 라인이 밀릴 수 있으니 정글러의 도움을 받기 위해 시야를 확보하세요.', item: '첫 코어로 내셔의 이빨을 선택하여 주문력과 공격 속도를 높이세요. 신발은 마오카이의 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 마오카이가 들어오는 타이밍에 맞춰 점화를 사용하면 마무리하기 좋아요.' },
    '말자하': { lv1: '말자하의 (P)\'공허 태세\'가 켜져 있으면 받는 피해가 줄고 군중 제어에 면역이 되니 (Q)\'맹독 폭발\'로 먼저 피해를 입혀 태세를 풀어 주세요. (Q)\'공허의 부름\'의 침묵에 걸리면 스킬을 쓸 수 없으니 문이 열리는 방향을 확인하며 피하세요. 1~2레벨에는 (Q)\'맹독 폭발\'을 적중시켜 이동 속도를 얻으며 거리 조절을 해요.', lv3: '(E)\'재앙의 환상\'과 (W)\'공허의 무리\'가 겹치면 지속 피해가 강하므로 짧게 딜교환하고 빠지세요. (Q)\'맹독 폭발\'로 독을 묻힌 뒤 (E)\'쌍독니\'를 빠르게 사용해 체력을 회복하며 압박하세요. 상대가 다가오면 (W)\'독기의 늪\'을 깔아 이동 속도를 늦추고 (E)\'쌍독니\'를 맞히기 쉽게 만드세요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없고 제압 중에는 스킬을 쓸 수 없으니 무리하게 진입하지 마세요. (P)\'공허 태세\'가 켜져 있으면 군중 제어에 면역이므로 먼저 (Q)\'맹독 폭발\'로 피해를 주어 태세를 푼 뒤 (R)\'석화의 응시\'를 사용하세요. 라인 관리 시 (Q)\'맹독 폭발\'로 미니언을 정리하며 정글러의 개입에 대비하세요.', item: '리안드리의 고통을 첫 코어로 선택해 지속 피해와 체력을 챙겨 말자하의 견제를 버티세요. 신발은 (Q)\'공허의 부름\'의 침묵 지속 시간을 줄여 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 정화로는 (R)\'황천의 손아귀\' 제압을 풀 수 없으니 운영을 위해 순간이동을 사용하세요.' },
    '말파이트': { lv1: '말파이트는 (Q)\'지진의 파편\'으로 피해를 주며 이동 속도를 훔치는데, 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. (Q)\'맹독 폭발\'을 사용해 적을 중독시키고 자신의 이동 속도를 높여 (Q)\'지진의 파편\'의 둔화 효과를 상쇄하세요. (P)\'화강암 방패\'가 켜져 있을 때는 피해가 흡수되니 보호막이 사라진 뒤에 (E)\'쌍독니\'로 짧게 딜교환하세요.', lv3: '(E)\'지면 강타\'를 맞으면 공격 속도가 줄어들고 마법 피해도 입으니 사거리 안에서 오래 버티지 마세요. 말파이트가 (W)\'천둥소리\'를 켜고 평타를 치러 다가올 때 (W)\'독기의 늪\'을 깔아 접근을 늦추고 둔화시키세요. 중독된 상태에서 (E)\'쌍독니\'를 계속 사용해 체력을 회복하며 말파이트의 체력을 깎는 것이 중요해요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 (R)\'석화의 응시\' 같은 군중 제어로 막을 수 없고 맞으면 공중에 떠서 스킬을 쓸 수 없어요. 돌진 방향을 읽고 옆으로 비켜서거나 점멸로 피한 뒤 딜교환을 시작하세요. 정글러가 근처에 있다면 말파이트의 돌진 사거리 밖에서 (Q)\'맹독 폭발\'로 라인을 관리하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 높은 말파이트에게 지속적인 마법 피해를 입히세요. 신발은 (Q)\'지진의 파편\'의 둔화와 (E)\'지면 강타\'의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. (R)\'멈출 수 없는 힘\'의 돌진을 피하기 위해 점멸이 필요하며, 순간이동으로 팀 합류를 도와야 해요.' },
    '모데카이저': { lv1: '(Q)\'맹독 폭발\'로 계속 견제하면서 모데카이저가 접근하지 못하게 거리를 유지하세요. (Q)\'말살\'은 단일 대상에게 적중할 때 피해가 커지니 미니언 옆에 서서 피해를 분산시키세요. 공격을 세 번 허용하면 (P)\'암흑 탄생\' 오라가 켜져 주변 피해가 늘어나니 주의하세요.', lv3: '(E)\'죽음의 손아귀\'에 끌려가면 바로 (Q)\'말살\' 연계가 들어오니 상대의 스킬 사거리를 세심하게 살피세요. (E)\'죽음의 손아귀\'가 빠진 시점에 (Q)\'맹독 폭발\'을 맞히고 (E)\'쌍독니\'를 빠르게 연사해 체력을 회복하며 공격하세요. (W)\'독기의 늪\'은 상대의 이동 속도를 늦춰 (E)\'쌍독니\'를 더 편하게 맞히는 용도로 사용하세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 수은 장식띠로도 빠져나올 수 없으니 안에서 최대한 버티며 싸워야 해요. 모데카이저가 다가올 때 (R)\'석화의 응시\'를 사용하여 기절시키면 공격 흐름을 끊고 거리를 벌릴 수 있어요. 상대의 궁극기가 빠진 후에는 (Q)\'맹독 폭발\'과 (E)\'쌍독니\'로 체력을 깎으며 정글러의 개입을 기다리세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 높은 모데카이저에게 지속적인 화상 피해를 입히세요. 신발은 마법 저항력을 높이고 강인함으로 군중 제어 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'불멸\'의 보호막을 체력으로 회복할 때 점화의 치유 감소 효과가 회복량을 줄여 킬각을 잡기 편해요.' },
    '문도박사': { lv1: '문도 박사가 (Q)\'오염된 뼈톱\'을 던지면 미니언 뒤에 숨어서 피해를 피하세요. (Q)\'맹독 폭발\'로 적을 중독시킨 뒤 (E)\'쌍독니\'를 사용해 지속적으로 체력을 깎으며 견제해요. 문도 박사는 체력 재생이 높으니 깎아 둔 체력이 돌아오기 전에 꾸준히 독을 묻히세요.', lv3: '문도 박사가 (W)\'심장 전기 충격\'을 사용하여 주변에 피해를 줄 때는 거리를 벌려 피해를 최소화하세요. (W)\'독기의 늪\'을 문도 발밑에 깔아 둔화시키고 접근을 방해해요. 적이 중독되었을 때 (E)\'쌍독니\'를 맞춰야 더 큰 피해를 주고 자신의 체력을 회복할 수 있어요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 사용해 체력을 대량으로 회복하면 무리하게 추격하지 마세요. (R)\'석화의 응시\'를 사용해 문도를 기절시키고 (E)\'쌍독니\'로 빠르게 몰아붙여야 해요. 문도 박사가 패시브로 첫 이동 불가 효과를 저항할 수 있으니 (R)\'석화의 응시\'를 맞히는 타이밍을 잘 조절하세요.', item: '문도 박사의 강력한 회복을 억제하기 위해 모렐로노미콘을 첫 코어로 가세요. 신발은 문도 박사의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 문도 박사의 (R)\'최대 투여량\'과 지속적인 체력 회복을 억제하기 위해 점화가 필요해요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'의 사거리가 더 길어서 초반 견제가 매우 아파요. (Q)\'맹독 폭발\'을 맞혀 이동 속도를 높이며 빠르게 움직여 화살을 피하세요. 무리하게 다가가기보다 웨이브를 통해 거리 조절을 하며 체력을 보존하세요.', lv3: '(W)\'독기의 늪\'을 바루스 발밑에 깔아 이동 속도를 늦추고 (E)\'쌍독니\'를 연사해 체력을 회복하세요. 바루스의 (E)\'퍼붓는 화살\' 장판 위에서는 (E)\'쌍독니\'의 체력 회복 효율이 떨어지니 그 구역을 빠르게 벗어나야 해요. 평타로 (W)\'역병 화살\'이 쌓인 상태에서 스킬을 맞으면 최대 체력 비례 피해가 크니 주의하세요.', lv6: '(R)\'부패의 사슬\'에 속박되면 이동이 막혀 바루스의 화력을 다 받게 되니 거리 조절에 유의하세요. 바루스가 궁극기를 빗맞혔을 때 (R)\'석화의 응시\'로 기절시킨 뒤 (E)\'쌍독니\'를 퍼부어 킬각을 잡으세요. 라인을 적당히 밀어 넣고 정글러와 함께 진입해 바루스를 압박하세요.', item: '판금 장화와 리안드리의 고통을 추천해요. 판금 장화는 바루스의 기본 공격 피해를 줄여주고 리안드리의 고통은 지속 피해로 원거리 상대에게 압박을 줘요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀 시간을 줄이고 점멸로 (R)\'석화의 응시\' 사거리 안으로 붙어 기절을 맞히세요.' },
    '베인': { lv1: '베인은 (W)\'은화살\'의 고정 피해를 입히기 위해 공격을 이어가니 거리를 유지하세요. (Q)\'맹독 폭발\'로 적을 중독시켜 이동 속도를 높이며 웨이브를 받아내세요. 초반에는 베인의 공격 사거리 내에서 무리하게 싸우지 않는 것이 중요해요.', lv3: '베인이 (Q)\'구르기\'를 사용하여 거리를 벌리거나 접근하지 못하도록 (W)\'독기의 늪\'을 발밑에 깔아주세요. 적이 중독된 상태라면 (E)\'쌍독니\'를 사용하여 높은 피해를 입히고 자신의 체력을 회복하세요. 베인의 (E)\'선고\'를 맞고 벽에 부딪히지 않도록 지형 근처에서는 주의해야 해요.', lv6: '베인이 (R)\'결전의 시간\'을 켜면 (Q)\'구르기\' 사용 시 투명해지므로 주의하고, 접근할 때 (R)\'석화의 응시\'로 기절시켜 킬각을 잡으세요. 베인의 (E)\'선고\'에 맞고 벽에 부딪히면 기절해서 스킬을 쓸 수 없으니 벽에서 떨어져 서세요. 라인 관리와 함께 정글러의 개입을 유도하며 싸우세요.', item: '판금 장화와 내셔의 이빨을 추천해요. 판금 장화는 베인의 기본 공격 피해를 줄여주고 내셔의 이빨은 지속적인 피해를 주는 데 도움을 줘요.', spell: '점멸과 점화를 추천해요. 베인이 (Q)\'구르기\'를 사용해 도망가기 전에 점화로 마무리하세요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'로 빠르게 접근해 기절을 걸려고 해요. (Q)\'맹독 폭발\'로 계속 중독시키며 거리를 유지하고, 상대가 달려들 때 뒤로 물러나며 딜교환을 하세요. 평타를 칠수록 (P)\'무자비한 폭풍\' 중첩이 쌓이니 길게 싸우지 말고 짧게 견제하세요.', lv3: '볼리베어가 (E)\'천공 분열\'로 보호막을 얻으려 할 때 그 범위를 피해 (E)\'쌍독니\'로 체력을 회복하세요. (W)\'광란의 상처\' 표식이 남았을 때는 추가 피해와 회복이 들어오니 잠시 거리를 벌려 주세요. (W)\'독기의 늪\'을 발밑에 깔아 접근 속도를 늦추고 중독 상태를 유지하며 계속 괴롭히세요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'로 도약해 들어올 때 (R)\'석화의 응시\'를 사용해 기절시키세요. 포탑을 비활성화하며 다이브를 시도할 수 있으니 체력이 낮을 때는 포탑 뒤라고 안심하지 말고 거리를 두세요. 상대의 돌진이 끝난 뒤 (Q)\'맹독 폭발\'과 (E)\'쌍독니\'를 반복해 체력을 깎아내세요.', item: '리안드리의 고통을 가서 체력이 높은 볼리베어에게 지속 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 볼리베어는 (W)\'광란의 상처\'로 체력을 회복하므로 점화로 회복량을 줄이는 것이 중요해요.' },
    '블라디미르': { lv1: '블라디미르가 (Q)\'수혈\'로 체력을 회복하며 다가올 때는 (Q)\'맹독 폭발\'을 먼저 맞춰 독을 묻히고 거리를 조절하세요. (Q)\'맹독 폭발\' 적중 후 얻는 이동 속도 증가를 활용해 (Q)\'수혈\'의 사거리 밖으로 빠르게 움직이는 것이 중요해요.', lv3: '블라디미르가 (W)\'피의 웅덩이\'를 사용하여 공격을 피하려 하면 (E)\'쌍독니\'를 아껴두었다가 웅덩이가 끝난 직후에 사용하세요. (E)\'선혈의 파도\'의 둔화 효과를 경계하며 (W)\'독기의 늪\'을 사용해 블라디미르의 움직임을 방해하세요.', lv6: '블라디미르가 (R)\'혈사병\'을 사용하여 받는 피해가 늘어나는 구간에는 싸우지 말고 즉시 거리를 벌리세요. (R)\'혈사병\' 효과가 사라진 뒤 (R)\'석화의 응시\'로 기절을 시킨 후 (E)\'쌍독니\'를 쏟아부어 킬각을 노려야 해요. 블라디미르가 체력을 희생해 (E)\'선혈의 파도\'를 충전하는 동안 (Q)\'맹독 폭발\'과 (E)\'쌍독니\'로 압박하면 회복하기 전에 체력을 깎을 수 있어요.', item: '헤르메스의 발걸음과 리안드리의 고통을 가세요. 헤르메스의 발걸음은 블라디미르의 마법 피해에 대비하고, 리안드리의 고통은 체력과 지속 피해를 챙겨 줘요.', spell: '점멸과 점화를 추천해요. 블라디미르의 (Q)\'수혈\'과 (R)\'혈사병\'으로 얻는 회복을 점화의 치유 감소로 줄이세요.' },
    '뽀삐': { lv1: '(Q)\'맹독 폭발\'로 적을 중독시켜 이동 속도를 얻으며 거리를 유지하세요. 뽀삐가 (Q)\'망치 강타\'로 둔화 지대를 만들며 다가오니 그 범위를 피해 계속 움직이세요. 첫 웨이브부터 계속 견제해서 뽀삐가 쉽게 다가오지 못하게 압박해요.', lv3: '뽀삐가 (E)\'용감한 돌진\'으로 벽에 밀쳐 기절시키려 하니 벽에서 멀리 떨어져 위치를 잡으세요. 뽀삐가 진입할 때 (W)\'독기의 늪\'을 깔면 상대의 돌진 스킬 사용을 막아 안전하게 거리를 벌릴 수 있어요. 중독된 뽀삐에게 (E)\'쌍독니\'를 빠르게 연사해서 체력을 회복하며 딜교환을 마무리하세요.', lv6: '뽀삐가 (R)\'수호자의 심판\'으로 밀어내려 할 때 타이밍에 맞춰 (R)\'석화의 응시\'를 사용해 기절시키고 딜을 넣으세요. 정글러가 개입할 때 뽀삐가 (W)\'굳건한 태세\'로 아군 돌진기를 막을 수 있으니 주의하며 라인을 관리해요. 뽀삐가 궁극기를 허공에 썼다면 (E)\'쌍독니\'로 강하게 압박해 킬각을 잡으세요.', item: '리안드리의 고통을 가서 체력이 높은 뽀삐에게 지속 피해를 입히세요. 신발은 뽀삐의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 추가 피해로 뽀삐를 빠르게 처치해 성장을 늦추세요.' },
    '사이온': { lv1: '(Q)\'맹독 폭발\'로 견제하며 거리를 유지하세요. (E)\'학살자의 포효\'는 미니언을 밀쳐내며 관통하니 미니언 뒤에 숨지 말고 옆으로 피하세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하면 범위 밖으로 빠르게 벗어나세요.', lv3: '(W)\'독기의 늪\'을 깔아 사이온의 접근을 늦추고 (E)\'쌍독니\'로 체력을 회복하며 피해를 입히세요. (W)\'영혼의 용광로\' 보호막이 켜진 동안은 피해가 흡수되니 보호막이 사라진 뒤에 딜교환을 하세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하는 빈틈에 빠르게 스킬을 쏟으세요.', lv6: '(R)\'멈출 수 없는 맹공\'은 저지 불가 상태로 돌진하니 (R)\'석화의 응시\'로 막으려 하지 말고 옆으로 비켜나세요. 돌진이 끝난 직후 정면에서 (R)\'석화의 응시\'를 사용해 기절시킨 뒤 빠르게 공격하세요. 처치 후 (P)\'영광스러운 죽음\' 상태일 때는 계속 거리를 벌리며 대응하세요.', item: '리안드리의 고통을 가서 체력이 많은 사이온에게 지속 피해를 입히세요. 신발은 마법 관통력을 높여주는 마법사의 신발을 추천해요.', spell: '점멸과 순간이동을 추천해요. 사이온의 돌진을 피하고 라인 복귀를 빠르게 하기 위해서예요.' },
    '사일러스': { lv1: '1~2레벨에는 (Q)\'사슬 후려치기\'의 둔화와 (P)\'페트리사이트 폭발\' 평타를 조심하며 거리를 유지하세요. (Q)\'맹독 폭발\'로 사일러스에게 독을 묻히며 지속적으로 견제하고 첫 웨이브를 안정적으로 가져오세요. 사일러스가 돌진기로 붙기 전에 최대한 멀리 떨어져서 행동해야 해요.', lv3: '사일러스가 (W)\'국왕시해자\'로 들어오며 체력을 회복하지 못하게 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막으세요. (Q)\'맹독 폭발\'로 먼저 중독시킨 뒤 (E)\'쌍독니\'를 맞춰서 피해를 주고 체력을 회복하는 것이 중요해요. 사일러스가 (E)\'도주 / 억압\' 사슬을 던질 때 옆으로 피하며 딜교환을 시도하세요.', lv6: '사일러스가 (R)\'강탈\'로 내 (R)\'석화의 응시\'를 가져가면 매우 위험해지니 주의해야 해요. 사일러스가 (W)\'국왕시해자\'로 들어오려고 할 때 (R)\'석화의 응시\'를 먼저 맞춰서 기절시키고 (W)\'독기의 늪\'으로 퇴로를 차단하세요. 라인을 빠르게 밀어 사일러스가 정글러의 개입에 대응하기 어렵게 만드세요.', item: '헤르메스의 발걸음을 먼저 올려 마법 저항력과 강인함을 챙기세요. 첫 코어 아이템으로는 공격 속도와 주문력을 동시에 올려주는 내셔의 이빨을 추천해요.', spell: '점멸과 점화를 추천해요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하는 것을 점화로 억제하여 킬각을 잡으세요.' },
    '세주아니': { lv1: '(Q)\'맹독 폭발\'을 사용해 세주아니를 중독시키고 이동 속도를 얻으며 거리를 유지해요. 세주아니가 (Q)\'혹한의 맹습\'으로 진입해 공중으로 띄우지 못하도록 주의하며 견제하세요.', lv3: '상대가 진입할 때 (W)\'독기의 늪\'을 깔아 (Q)\'혹한의 맹습\' 같은 이동 스킬을 사용하지 못하게 방해해요. (Q)\'맹독 폭발\'로 중독된 상대에게 (E)\'쌍독니\'를 빠르게 연사하며 피해를 입히고 체력을 회복하세요.', lv6: '(R)\'빙하 감옥\'에 맞으면 기절하며 큰 피해를 입으니 투사체가 날아올 때 주의하세요. 상대가 다가오면 (R)\'석화의 응시\'로 기절시킨 뒤 (E)\'쌍독니\'로 빠르게 몰아쳐서 킬각을 잡으세요. 정글러의 개입이 예상되면 (W)\'독기의 늪\'을 활용해 상대의 진입 경로를 차단하세요.', item: '헤르메스의 발걸음과 리안드리의 고통을 추천해요. 기절과 둔화의 지속 시간을 줄이고 체력이 많은 상대를 계속 불태워 피해를 입히기 위해서예요.', spell: '점멸과 순간이동을 선택해요. 갑작스러운 진입을 피하고 빠르게 라인에 복귀하기 위해서예요.' },
    '세트': { lv1: '(Q)\'맹독 폭발\'로 세트를 중독시켜 이동 속도를 얻으며 거리를 유지하세요. 세트가 (Q)\'주먹다짐\'을 사용해 이동 속도가 빨라지며 다가오면 뒤로 물러나 거리 조절을 하세요. 세트는 (P)\'투기장의 투지\'로 잃은 체력에 비례해 체력을 회복하니 깎아 둔 체력이 돌아오기 전에 꾸준히 독을 묻히세요.', lv3: '(W)\'독기의 늪\'을 깔아 세트의 이동을 둔화시키고 (E)\'쌍독니\'를 연사해 피해를 입히세요. 세트의 (W)\'강펀치\' 중심선에 맞으면 고정 피해를 입으니 옆으로 움직여 피해야 해요. 세트의 (E)\'안면 강타\'를 맞으면 기절할 수 있으니 미니언과 거리를 두며 주의하세요.', lv6: '세트가 (R)\'대미 장식\'을 쓰려고 접근할 때 (R)\'석화의 응시\'를 먼저 써서 기절시키세요. (R)\'대미 장식\'에 붙잡히면 제압이라 스킬을 쓸 수 없으니 사용 전에 거리를 벌리는 것이 중요해요. 세트의 (W)\'강펀치\' 보호막이 두꺼워지기 전에 (W)\'독기의 늪\'과 (E)\'쌍독니\'로 빠르게 압박하세요.', item: '리안드리의 고통을 첫 코어로 가서 세트에게 지속적인 마법 피해를 입히세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화를 신으세요.', spell: '점멸과 점화를 추천해요. 점화로 세트의 (P)\'투기장의 투지\'를 통한 체력 회복을 억제하며 킬을 노리세요.' },
    '쉔': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'을 사용하여 쉔을 중독시키며 거리를 유지하세요. 쉔이 (Q)\'황혼 강습\'으로 기의 검을 사용할 때 피해를 입지 않도록 조심하며 견제해요. 쉔이 스킬을 사용해 (P)\'기 보호막\'이 켜진 순간에는 무리하게 (E)\'쌍독니\'를 쓰지 마세요.', lv3: '쉔이 (W)\'의지의 결계\'를 펼쳐도 (E)\'쌍독니\' 같은 스킬 피해는 막을 수 없으니 적극적으로 딜교환을 하세요. 쉔이 (E)\'그림자 돌진\'으로 들어올 때 (W)\'독기의 늪\'을 미리 깔아 이동 스킬 사용을 방해하는 것이 좋아요. (E)\'그림자 돌진\'에 도발되면 스킬을 쓸 수 없으니 미리 대비하세요.', lv6: '쉔이 (R)\'단결된 의지\'를 사용하여 다른 라인에 합류하면 빠르게 라인을 밀어 압박하세요. 쉔이 진입할 때 (R)\'석화의 응시\'를 맞춰 기절시킨 뒤 (E)\'쌍독니\'로 몰아붙이면 킬각을 잡을 수 있어요. 쉔의 궁극기가 빠진 타이밍에 정글러와 함께 (W)\'독기의 늪\'을 활용해 싸우세요.', item: '체력이 높은 쉔에게 지속적인 피해를 입히기 위해 리안드리의 고통을 첫 코어로 가세요. 신발은 (E)\'그림자 돌진\'의 도발 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 쉔이 (P)\'기 보호막\'으로 버티려 할 때 점화를 사용하여 확실하게 킬을 내세요.' },
    '쉬바나': { lv1: '(Q)\'맹독 폭발\'을 활용해 쉬바나에게 지속적으로 피해를 입히고 거리를 유지하세요. 쉬바나가 (Q)\'잉걸불 일격\'을 사용하며 다가오면 뒤로 물러나며 거리 조절을 해주세요. 첫 웨이브부터 견제하며 상대의 체력을 깎아두는 것이 중요해요.', lv3: '쉬바나가 (W)\'지옥불 방패\'로 이동 속도를 얻고 달려들 때 발밑에 (W)\'독기의 늪\'을 깔아 둔화시키세요. (Q)\'맹독 폭발\'로 중독시킨 후 (E)\'쌍독니\'를 빠르게 연사하여 강력한 피해를 입히세요. 쉬바나의 (E)\'용암 분출\' 투사체를 무빙으로 피하며 딜교환을 유도하세요.', lv6: '(R)\'용의 강림\'은 저지 불가 상태로 도약하니 (R)\'석화의 응시\'로 끊으려 하지 말고 경로에서 벗어나세요. 도약이 끝난 뒤 정면에서 (R)\'석화의 응시\'를 사용해 기절시키고 (E)\'쌍독니\'로 체력을 깎아 킬각을 잡으세요. 라인을 당겨서 정글 개입에 대비하며 기회를 엿보세요.', item: '판금 장화와 리안드리의 고통을 추천해요. 판금 장화로 (Q)\'잉걸불 일격\'의 기본 공격 피해를 줄이고, 리안드리의 고통으로 쉬바나의 높은 체력을 효과적으로 깎을 수 있어요.', spell: '점멸과 점화를 추천해요. 점멸은 생존과 (R)\'석화의 응시\' 각을 잡는 데 쓰고, 점화는 용 형상의 쉬바나가 (W)\'지옥불 방패\' 폭발로 회복하는 양을 줄여 줘요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 번개를 쏴서 견제하고 (P)\'굶주린 새떼\'로 체력을 회복해요. (Q)\'맹독 폭발\'을 맞혀 이동 속도를 얻고 (E)\'쌍독니\'로 체력을 깎으며 거리를 유지하세요. 스웨인이 영혼 조각을 모아 최대 체력이 늘어나기 전에 계속 견제하는 게 좋아요.', lv3: '(E)\'속박명령\'은 파동이 돌아올 때 속박하고 끌어당기니 파동의 궤적을 보고 옆으로 피하세요. 스웨인이 다가오려 하면 (W)\'독기의 늪\'을 깔아 둔화를 걸고 접근을 늦추세요. (W)\'제국의 눈\'에 맞으면 둔화되니 주의하고 (Q)\'맹독 폭발\'과 (E)\'쌍독니\'로 끊임없이 피해를 입히세요.', lv6: '스웨인이 (R)\'악의 승천\'을 켜면 주변 체력을 흡수하니 무리하게 붙지 말고 (R)\'석화의 응시\'로 기절시켜 흐름을 끊으세요. (W)\'독기의 늪\'을 활용해 스웨인이 다가오지 못하게 막으면서 원거리에서 화력을 쏟으세요. 정글러가 오기 전까지 (W)\'제국의 눈\'의 시야 확보에 주의하며 라인을 관리하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 많은 스웨인에게 지속 피해를 입히세요. 신발은 (E)\'속박명령\'의 속박 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'악의 승천\'과 (P)\'굶주린 새떼\'의 강력한 체력 회복을 점화로 억제해야 해요.' },
    '스카너': { lv1: '(Q)\'맹독 폭발\'을 사용하여 지속적으로 견제하며 거리를 유지하세요. 스카너가 (Q)\'부서진 대지/지반 돌출\'을 켜고 다가올 때 평타 사거리를 주지 않도록 주의하며 뒤로 물러나세요. 첫 웨이브부터 독을 묻혀 체력을 깎아두는 것이 중요해요.', lv3: '스카너가 (E)\'이쉬탈의 격돌\'로 진입하려고 하면 발밑에 (W)\'독기의 늪\'을 깔아 이동 기술 사용을 막으세요. (Q)\'맹독 폭발\'로 중독시킨 후 (E)\'쌍독니\'를 빠르게 연사하여 피해를 입히고 체력을 회복하세요. 상대의 (W)\'대지의 수호자\' 보호막이 빠진 타이밍에 딜교환을 시도하는 것이 좋아요.', lv6: '스카너가 접근할 때 정면에서 (R)\'석화의 응시\'를 맞혀 기절시켜 (R)\'꿰뚫기\'를 쓰지 못하게 하세요. (R)\'꿰뚫기\'에 제압당하면 스킬을 쓸 수 없고 정화로도 풀 수 없으니 거리를 지키는 것이 중요해요. 정글러가 개입할 때 상대의 제압 스킬 사거리를 계산하며 라인을 당겨 유지하세요.', item: '판금 장화와 리안드리의 고통을 추천해요. 판금 장화로 스카너의 기본 공격 피해를 줄이고, 리안드리의 고통으로 체력이 많은 상대를 지속적으로 압박하세요.', spell: '점멸과 순간이동을 추천해요. 점멸로 스카너의 돌진기를 피하고, 순간이동으로 라인 복귀와 운영에 집중하세요.' },
    '신지드': { lv1: '1~2레벨 구간에는 신지드가 (Q)\'맹독의 자취\'를 켜고 라인을 밀며 접근할 때 (Q)\'맹독 폭발\'로 독을 묻히며 견제하세요. 독구름 위에 계속 서 있으면 체력이 빨리 빠지니 미니언 사이로 위치를 잡으며 거리를 조절해요.', lv3: '신지드가 (W)\'초강력 접착제\'를 던진 위치로 (E)\'던져넘기기\'를 사용해 속박을 노릴 수 있으니 주의하세요. 신지드가 들어올 때 (W)\'독기의 늪\'을 깔아 둔화를 걸고, 독이 묻은 대상에게 (E)\'쌍독니\'를 계속해서 사용해 체력을 회복하며 딜교환하세요.', lv6: '신지드가 (R)\'광기의 물약\'을 사용하면 고통스러운 상처 효과로 인해 회복이 줄어드니 주의하세요. 신지드가 접근할 때 (R)\'석화의 응시\'로 기절시키고 (E)\'쌍독니\'를 쏟아부으면 킬을 노릴 수 있어요. 신지드가 궁극기를 켜고 무리하게 밀고 들어오면 정글러를 호출하며 라인을 관리하세요.', item: '첫 코어로 리안드리의 고통을 선택해 지속적인 피해를 입히는 것이 좋아요. 신발은 신지드의 마법 피해와 군중 제어를 견디기 위해 헤르메스의 발걸음을 신으세요.', spell: '점멸과 정화를 추천해요. (W)\'초강력 접착제\'에 걸리는 둔화와 그 위에 착지했을 때 발생하는 속박을 정화로 풀 수 있어요.' },
    '신짜오': { lv1: '초반 웨이브부터 (Q)\'맹독 폭발\'을 사용해 거리 조절을 하며 지속적으로 체력을 깎으세요. 신짜오가 (Q)\'삼조격\'으로 띄우려 할 때 뒤로 물러나며 공격 사거리 밖을 유지해요.', lv3: '신짜오가 (E)\'무쌍돌격\'으로 진입하면 즉시 발밑에 (W)\'독기의 늪\'을 깔아 추가 이동 기술 사용을 막으세요. 중독된 상대에게 (E)\'쌍독니\'를 빠르게 연사하여 큰 피해를 입히고 체력을 회복해요.', lv6: '진입하는 신짜오를 (R)\'석화의 응시\'로 기절시켜 딜교환 주도권을 잡으세요. 상대가 (R)\'현월수호\'를 사용하면 원거리 공격이 막히므로 무리하게 공격하지 말고 신중하게 거리를 벌려요.', item: '판금 장화와 리안드리의 고통을 가세요. 판금 장화는 신짜오의 기본 공격 피해를 줄여주고 리안드리의 고통은 체력이 높은 적에게 지속 피해를 입혀요.', spell: '점멸과 점화를 추천해요. 점멸로 위험한 상황을 회피하고 점화로 신짜오의 (P)\'결심\' 회복 효과를 감소시켜 킬각을 잡으세요.' },
    '아이번': { lv1: '미니언 뒤에 숨어 (Q)\'덩굴뿌리\'를 피하며 (Q)\'맹독 폭발\'로 계속 견제하세요. 독에 맞은 적에게 (E)\'쌍독니\'를 사용해 체력을 회복하며 거리를 유지하는 것이 중요해요. 상대가 다가오지 못하게 지속적으로 압박하며 경험치 주도권을 가져가세요.', lv3: '(Q)\'덩굴뿌리\'에 속박되지 않도록 주의하며 (W)\'독기의 늪\'을 깔아 상대의 돌진을 차단하세요. (W)\'독기의 늪\' 위에 있는 적에게 (E)\'쌍독니\'를 연사해 빠르게 체력을 깎아내는 구도를 만드세요. 상대의 (E)\'보호의 씨앗\' 보호막이 터질 때 둔화되지 않도록 무빙에 신경 써야 해요.', lv6: '(R)\'데이지!\'가 소환되면 데이지의 연속 공격이 공중으로 띄우니 거리를 벌리며 (Q)\'맹독 폭발\'로 견제하세요. 아이번이 가까이 오면 정면에서 (R)\'석화의 응시\'로 기절시켜 흐름을 끊으세요. 정글러가 개입할 때 (W)\'독기의 늪\'으로 진입 경로를 막아 아군을 보호하세요.', item: '헤르메스의 발걸음과 루덴의 메아리를 추천해요. 강인함으로 (Q)\'덩굴뿌리\'의 속박 시간을 줄이고 마나와 주문력을 확보해 견제력을 높이기 위해서예요.', spell: '점멸과 순간이동을 추천해요. (Q)\'덩굴뿌리\'를 피하거나 (R)\'석화의 응시\' 각을 잡기 위해 점멸이 필요하며, 탑 라인 유지력을 위해 순간이동이 효율적이에요.' },
    '아지르': { lv1: '(Q)\'맹독 폭발\'로 견제하며 이동 속도를 얻어 거리 조절을 해요. 아지르가 (W)\'일어나라!\'로 병사를 세워 견제할 때 무리하게 다가가지 마세요. 첫 웨이브에서는 (Q)\'맹독 폭발\'을 맞히고 (E)\'쌍독니\'로 짧게 딜교환하며 체력을 관리하세요.', lv3: '아지르가 (E)\'신기루\'로 진입하거나 도망가려 할 때 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막으세요. (W)\'독기의 늪\' 위에 있는 적에게 (E)\'쌍독니\'를 빠르게 사용해 큰 피해를 입히고 체력을 회복하세요. (Q)\'사막의 맹습\'의 둔화 효과를 피하며 거리 조절에 집중하세요.', lv6: '(R)\'석화의 응시\'로 적을 기절시킨 뒤 (E)\'쌍독니\'를 쏟아부어 킬각을 잡으세요. 아지르가 (R)\'황제의 진영\'으로 밀어내려 할 때 반응하여 위치를 잡는 것이 중요해요. 라인을 당겨 정글 개입을 유도하고 (R)\'석화의 응시\'의 사거리를 활용해 압박하세요.', item: '헤르메스의 발걸음과 균열 생성기를 가세요. 마법 저항력으로 아지르의 피해를 줄이고 체력과 주문력으로 지속 교전 능력을 높이기 위해서예요.', spell: '점멸과 순간이동을 추천해요. 필수적인 생존기와 탑 라인 유지력을 위해 선택하세요.' },
    '아칼리': { lv1: '(Q)\'맹독 폭발\'로 계속 견제하며 아칼리가 (Q)\'오연투척검\'으로 둔화를 걸고 다가오지 못하게 거리를 유지하세요. 아칼리가 (P)\'암살자의 표식\' 원 경계를 넘으며 강화 평타를 노릴 때 (Q)\'맹독 폭발\'로 얻은 이동 속도를 활용해 뒤로 물러나세요. 무리하게 평타를 치기보다 스킬로만 체력을 깎으며 압박하세요.', lv3: '아칼리가 (E)\'표창곡예\'로 표식을 남겼을 때 발밑에 (W)\'독기의 늪\'을 깔면 아칼리가 돌진 스킬을 사용할 수 없게 돼요. (W)\'황혼의 장막\' 안의 아칼리는 대상 지정이 안 되므로 (E)\'쌍독니\' 대신 (Q)\'맹독 폭발\'로 지속 피해를 입히세요. 연막 밖으로 나오는 순간 (E)\'쌍독니\'를 빠르게 연사해 체력을 회복하며 피해를 주세요.', lv6: '(R)\'무결처형\'으로 빠르게 진입하는 아칼리를 정면에서 (R)\'석화의 응시\'로 기절시켜 돌진 흐름을 끊으세요. (R)\'석화의 응시\'가 빠진 뒤에는 (W)\'황혼의 장막\'과 궁극기를 이용해 들어오기 쉬우니 정글 개입을 요청하며 사리세요. 라인을 밀어두고 포탑 근처에서 (W)\'독기의 늪\'을 활용해 진입 경로를 차단하는 것이 좋아요.', item: '리안드리의 고통을 첫 코어로 가서 지속 피해를 주고 체력을 높여 생존력을 챙기세요. 신발은 아칼리의 마법 피해를 줄이고 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 아칼리의 체력을 깎아 마무리 피해를 더하고 킬각을 잡으세요.' },
    '아크샨': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'을 맞춰서 이동 속도를 얻으며 거리를 조절하세요. (Q)\'복수의 부메랑\'은 맞을수록 사거리가 늘어나니 날아오는 경로를 보고 옆으로 비켜서세요.', lv3: '3레벨 이후에는 (W)\'독기의 늪\'을 사용해 아크샨의 (E)\'영웅의 비상\' 돌진을 막는 것이 중요해요. (Q)\'맹독 폭발\'로 중독시킨 뒤 (E)\'쌍독니\'를 맞춰서 체력을 회복하며 딜교환을 진행하세요.', lv6: '(R)\'석화의 응시\'로 아크샨을 기절시키면 (E)\'쌍독니\'를 연사해 킬을 노릴 수 있어요. (R)\'인과응보\'는 내가 잃은 체력이 많을수록 피해가 커지고 처음 맞는 미니언에도 막히니 체력이 낮을 때는 미니언 뒤에 서세요.', item: '판금 장화와 리치베인을 가요. 판금 장화는 아크샨의 기본 공격 피해를 줄이고, 리치베인은 스킬을 쓴 뒤 다음 기본 공격에 추가 마법 피해를 더해 줘요.', spell: '점멸과 점화를 추천해요. 점화의 지속 고정 피해로 체력이 낮아진 아크샨을 마무리하세요.' },
    '아트록스': { lv1: '(Q)\'맹독 폭발\'로 계속 견제하며 거리 조절을 하세요. 아트록스가 (Q)\'다르킨의 검\' 끝자락으로 띄우려 할 때 옆으로 피해 주세요. (P)\'사신 태세\'가 적용된 평타 교환은 피하고 원거리에서 독을 묻히는 데 집중하세요.', lv3: '(W)\'지옥사슬\'에 맞으면 즉시 범위 밖으로 나가서 끌려가지 않게 주의하세요. 아트록스가 (E)\'파멸의 돌진\'으로 진입할 때 (W)\'독기의 늪\'을 깔면 돌진을 막고 이동 속도를 늦출 수 있어요. 독이 묻은 상태에서 (E)\'쌍독니\'를 빠르게 연사해 체력을 회복하며 딜교환하세요.', lv6: '아트록스가 (R)\'세계의 종결자\'를 켜고 달려들 때 정면에서 (R)\'석화의 응시\'를 사용해 기절시키세요. 기절시킨 동안 (E)\'쌍독니\'를 쏟아부어 빠르게 피해를 입히는 것이 중요해요. 정글러가 올 때 (W)\'독기의 늪\'으로 상대의 도주 경로를 차단해 함께 잡으세요.', item: '모렐로노미콘을 첫 코어로 선택해 고통스러운 상처로 아트록스의 회복량을 줄이세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. (E)\'파멸의 돌진\'과 (P)\'사신 태세\'의 회복력을 점화의 치유 감소로 억제해 킬각을 잡기 편해요.' },
    '암베사': { lv1: '암베사가 (P)\'용사냥개의 발걸음\'으로 빠르게 거리를 좁히려 해요. (Q)\'맹독 폭발\'을 적중시켜 이동 속도를 얻어 거리를 벌리고, (Q)\'교활한 휩쓸기\'의 바깥 날 범위에 맞지 않도록 주의하세요. 상대가 스킬을 헛사용했을 때 평타로 압박하세요.', lv3: '암베사가 진입할 때 발밑에 (W)\'독기의 늪\'을 깔아 (P)\'용사냥개의 발걸음\' 돌진을 막으세요. (W)\'배척\'의 보호막이 유지되는 동안 피해를 주면 이후 입히는 물리 피해량이 늘어나니 잠시 공격을 멈추세요. 보호막이 사라진 뒤 (E)\'쌍독니\'를 연사해 체력을 회복하며 딜교환하세요.', lv6: '(R)\'공개 처형\'은 저지 불가 상태로 가장 멀리 있는 적에게 순간이동해 제압하니 (R)\'석화의 응시\'로 막을 수 없고, 제압 중에는 어떤 스킬도 쓸 수 없어요. 평소 접근하는 암베사는 정면에서 (R)\'석화의 응시\'로 기절시켜 연계를 끊으세요. 정글러가 올 때 (W)\'독기의 늪\'으로 적의 도주 경로를 차단하세요.', item: '리안드리의 고통과 판금 장화를 추천해요. 리안드리의 고통으로 지속 피해를 주고, 판금 장화의 효과로 암베사의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 암베사가 (R)\'공개 처형\'의 기본 지속 효과로 체력을 회복하므로 점화로 이를 억제하는 게 중요해요.' },
    '애니비아': { lv1: '(Q)\'냉기 폭발\' 구체가 날아오는 경로를 보고 옆으로 피해서 기절을 피하세요. (Q)\'맹독 폭발\'로 적을 중독시켜 이동 속도를 얻으며 거리를 유지하고 견제하세요. 애니비아가 구체를 날린 직후에 다가가서 (Q)\'맹독 폭발\'과 평타로 응수하세요.', lv3: '애니비아가 (W)\'결정화\'로 벽을 세워 접근을 막으려 하니 벽이 사라질 때까지 기다리거나 옆으로 돌아서 가세요. (Q)\'냉기 폭발\'이 빠진 타이밍에 (W)\'독기의 늪\'을 깔고 (E)\'쌍독니\'를 빠르게 연사해 체력을 회복하며 딜교환하세요. (E)\'동상\' 피해를 줄이기 위해 (Q)\'냉기 폭발\'에 맞지 않는 것이 가장 중요해요.', lv6: '(R)\'얼음 폭풍\'의 둔화 구역 안에서는 (R)\'석화의 응시\'를 맞히기 어려우니 장판 밖으로 유인한 뒤 기절을 거세요. (R)\'석화의 응시\'로 애니비아를 기절시킨 후 (E)\'쌍독니\'를 퍼부어 빠르게 체력을 깎으세요. 애니비아가 쓰러져도 (P)\'환생\'으로 다시 살아나니 알이 깨질 때까지 계속 공격하세요.', item: '리안드리의 고통과 헤르메스의 발걸음을 추천해요. 리안드리의 고통은 체력을 제공하고 지속 피해를 입히며, 헤르메스의 발걸음은 마법 저항력을 높이고 기절 지속시간을 줄여줘요.', spell: '점멸과 정화를 추천해요. (Q)\'냉기 폭발\'의 기절이나 (R)\'얼음 폭풍\'의 둔화를 정화로 빠르게 풀고 공격할 수 있어요.' },
    '야스오': { lv1: '(Q)\'맹독 폭발\'로 미니언과 야스오를 견제하며 거리를 유지하세요. 야스오의 (P)\'낭인의 길\' 보호막이 있을 때는 무리하게 딜교하지 말고 보호막이 빠진 뒤에 (E)\'쌍독니\'를 사용하세요. (Q)\'강철 폭풍\' 중첩이 쌓이지 않도록 주의하며 첫 웨이브를 받아먹으세요.', lv3: '야스오가 (E)\'질풍검\'으로 들어오려 할 때 (W)\'독기의 늪\'을 깔아 이동기를 봉쇄하세요. 야스오의 (W)\'바람 장막\'은 투사체만 막으니 장막이 서 있는 동안은 (E)\'쌍독니\'를 아끼고 사라진 뒤에 공격을 이어가세요. 독에 걸린 야스오에게 (E)\'쌍독니\'를 맞히며 체력을 회복하고 압박하세요.', lv6: '야스오가 (Q)\'강철 폭풍\'을 두 번 맞혀 띄우기 전에 정면에서 (R)\'석화의 응시\'를 써서 기절시키세요. 공중에 뜨면 스킬을 쓸 수 없고 (R)\'최후의 숨결\'로 이어질 수 있으니 미니언 사이에서 거리를 조절하며 중첩을 피하세요. 정글러가 올 경우 (W)\'독기의 늪\'을 활용해 야스오의 진입을 차단하며 싸우세요.', item: '첫 코어 아이템으로 내셔의 이빨을 올려 공격 속도와 주문력을 챙기세요. 신발은 야스오의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 야스오의 (P)\'낭인의 길\' 보호막이 깨진 순간 점화를 사용하면 킬을 따내기 쉬워요.' },
    '오공': { lv1: '(Q)\'맹독 폭발\'로 먼저 견제하며 오공이 접근하지 못하게 거리 조절을 하세요. 오공이 (Q)\'파쇄격\'으로 사거리를 늘려 공격하려 하면 뒤로 빠지며 계속 독을 묻히세요. 무리하게 붙어 싸우면 (P)\'바위 피부\' 때문에 오공이 더 단단해지니 짧게 교환하고 빠지세요.', lv3: '오공이 (E)\'근두운 급습\'이나 (W)\'분신 전사\'로 진입할 때 발밑에 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막으세요. 늪에 걸린 오공에게 (Q)\'맹독 폭발\'을 맞히고 (E)\'쌍독니\'를 연사해 체력을 회복하며 피해를 입히세요. (W)\'분신 전사\'의 분신에 스킬을 낭비하지 않도록 진짜 오공의 움직임을 잘 살피세요.', lv6: '오공이 (R)\'회전격\'을 쓰며 빠르게 다가올 때 정면에서 (R)\'석화의 응시\'를 사용해 기절시키세요. 공중에 뜨면 스킬을 사용할 수 없으니 (R)\'회전격\'에 맞지 않도록 빠르게 반응하는 것이 중요해요. 라인 관리 중 정글러가 오면 (W)\'독기의 늪\'으로 진입로를 차단해 대응 시간을 버세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 많은 오공에게 지속 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'바위 피부\'로 인한 체력 재생을 억제하고 낮은 체력의 오공을 마무리하기 좋아요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 던지고 다시 불러들이며 두 번의 피해를 주니 옆으로 피하세요. (Q)\'맹독 폭발\'을 적중시켜 중독시킨 후 (E)\'쌍독니\'로 체력을 회복하며 거리 조절을 하세요. 첫 웨이브부터 견제하며 오로라가 다가오지 못하게 압박하세요.', lv3: '오로라가 (W)\'장막 너머로\'를 사용해 투명해지면 무리하게 쫓지 말고 기다리세요. 오로라가 (E)\'마법의 문\'으로 도약하려 할 때 (W)\'독기의 늪\'을 깔면 이동 스킬 사용을 막아 딜교환을 이끌 수 있어요. (Q)\'맹독 폭발\'로 중독시킨 뒤 (E)\'쌍독니\'를 빠르게 연사해 피해를 누적시키세요.', lv6: '오로라가 (R)\'세계의 경계\' 영역을 생성하면 안에서 빠르게 이동하며 공격하니 영역 밖으로 나가세요. 오로라가 영역 내에서 점프하는 타이밍에 맞춰 (R)\'석화의 응시\'를 사용해 기절시킨 뒤 빠르게 정리하세요. (W)\'독기의 늪\'으로 도주 경로를 차단하고 정글러의 개입을 기다리며 라인을 관리하세요.', item: '내셔의 이빨을 첫 코어로 선택해 주문력과 공격 속도를 챙기고 기본 공격에 추가 마법 피해를 더하세요. 신발은 오로라의 둔화와 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 오로라가 (P)\'영혼 방호술\'로 체력을 회복하는 것을 점화로 억제하며 킬각을 잡으세요.' },
    '오른': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'을 계속 맞춰서 오른의 체력을 깎고 이동 속도를 높이세요. (Q)\'용암 균열\'의 균열 지점을 확인하고 옆으로 비켜나서 둔화를 피하는 것이 중요해요. 무리하게 다가가지 말고 거리 조절을 하며 독 피해를 입히세요.', lv3: '(W)\'독기의 늪\'을 오른의 발밑에 깔아 (E)\'화염 돌진\' 같은 이동 기술을 사용하지 못하게 막으세요. (W)\'불꽃 풀무질\'의 마지막 불꽃에 맞으면 불안정 상태가 되니 오른이 전진하는 경로에서 벗어나세요. (Q)\'맹독 폭발\'로 중독시킨 뒤 (E)\'쌍독니\'를 빠르게 연사하며 체력을 회복하세요.', lv6: '(R)\'대장장이 신의 부름\'으로 소환된 정령이 다가올 때 정면으로 마주하지 말고 옆으로 피하세요. 오른이 정령을 박치기해 돌진해올 때 (R)\'석화의 응시\'를 사용해 기절시켜 진입을 끊으세요. (W)\'독기의 늪\'을 적절히 사용해 정글러의 개입이나 오른의 추가 진입을 차단하며 라인을 유지하세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 오른에게 지속적인 피해를 입히세요. 신발은 마법 관통력을 높여주는 마법사의 신발이 좋아요.', spell: '점멸과 순간이동을 추천해요. 오른의 강력한 군중 제어기를 피하고 라인 복귀를 통해 경험치 손실을 줄여야 해요.' },
    '올라프': { lv1: '1~2레벨 구간에는 올라프의 (Q)\'역류\'를 맞지 않도록 거리를 조절하며 (Q)\'맹독 폭발\'로 견제하세요. 올라프가 도끼를 던지고 주우러 오는 동안 (Q)\'맹독 폭발\'을 맞춰 독을 묻히는 것이 중요해요. 초반에는 올라프의 평타와 스킬이 강력하니 무리하게 붙지 마세요.', lv3: '(Q)\'맹독 폭발\'로 적을 중독시킨 뒤 (E)\'쌍독니\'를 사용해야 큰 피해를 주고 체력을 회복할 수 있어요. 올라프가 (W)\'버티기\'를 사용해 보호막을 얻는 동안에는 딜교환을 피하고, (W)\'독기의 늪\'을 깔아 올라프의 움직임을 둔화시키세요. 올라프의 (Q)\'역류\'를 피하면서 독을 묻히는 것에 집중하세요.', lv6: '올라프가 (R)\'라그나로크\'를 사용하면 이동 방해 효과에 면역이 되므로 (R)\'석화의 응시\'를 아껴두세요. 궁극기가 끝난 뒤에 (R)\'석화의 응시\'를 맞춰 기절시킨 후 (E)\'쌍독니\'로 몰아붙이면 킬각을 잡을 수 있어요. 올라프가 낮은 체력에서 (P)\'광전사의 분노\'로 흡혈하는 것을 경계하며 라인 관리에 신경 쓰세요.', item: '리안드리의 고통을 첫 코어로 올려 지속적인 피해를 입히세요. 신발은 물리 피해를 줄여주는 판금 장화로 선택하세요.', spell: '점멸과 점화를 추천해요. 올라프의 (P)\'광전사의 분노\'로 늘어난 생명력 흡수를 점화의 치유 감소로 억제하세요.' },
    '요네': { lv1: '(Q)\'맹독 폭발\'로 지속적으로 견제하며 이동 속도를 높여 거리를 유지하세요. 요네가 (Q)\'필멸의 검\'을 두 번 맞히면 돌진하며 띄우니, 첫 중첩 이후에는 무빙으로 두 번째 공격을 피하세요. (P)\'사냥꾼의 길\'로 인한 마법 피해가 섞인 평타 교환은 짧게 끝내세요.', lv3: '요네가 (E)\'영혼해방\'으로 진입할 때 발밑에 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막으세요. (W)\'영혼 가르기\' 보호막이 켜진 동안에는 (E)\'쌍독니\'를 아꼈다가 보호막이 사라진 뒤에 빠르게 사용하세요. (Q)\'필멸의 검\' 돌풍을 피한 직후 (Q)\'맹독 폭발\'과 (E)\'쌍독니\' 연계로 피해를 입히세요.', lv6: '요네가 (R)\'운명봉인\'으로 들어오는 순간 (R)\'석화의 응시\'를 사용하여 기절시키고 흐름을 끊으세요. (E)\'영혼해방\'이 빠진 상태에서는 빠지기 어려워지니 (W)\'독기의 늪\'과 (E)\'쌍독니\'로 강하게 압박하세요. 정글러가 올 때 (R)\'운명봉인\'에 적중되어 한 번에 잡힐 수 있으니 라인을 적절히 관리하세요.', item: '판금 장화와 리안드리의 고통을 가세요. 판금 장화로 (P)\'사냥꾼의 길\'과 평타 피해를 줄이고, 리안드리의 고통으로 체력을 챙기며 지속 피해를 입히기 좋아요.', spell: '점멸과 점화를 추천해요. 요네의 체력이 낮을 때 점화의 지속 고정 피해로 마무리하기 좋아요.' },
    '요릭': { lv1: '요릭이 (Q)\'최후의 의식\'으로 미니언을 처치해 무덤을 쌓지 못하도록 (Q)\'맹독 폭발\'로 꾸준히 견제하며 거리를 유지하세요. (E)\'애도의 안개\'에 맞아 표식이 남으면 안개 망령들이 달려드니 구체가 날아오는 방향을 보고 피해야 해요. 초반에는 요릭의 (Q)\'최후의 의식\' 회복량을 고려하며 짧게 끊어서 딜교환을 하세요.', lv3: '(Q)\'맹독 폭발\'로 먼저 적을 중독시킨 뒤 (E)\'쌍독니\'를 사용해 강력하게 압박하세요. 요릭이 (W)\'망자의 진\'으로 길을 막으면 (W)\'독기의 늪\'으로 요릭의 접근 속도를 늦추세요. (E)\'애도의 안개\' 표식이 붙은 상태에서 안개 망령이 쫓아오면 (E)\'쌍독니\'로 체력을 회복하며 맞대응하세요.', lv6: '요릭이 (R)\'군도의 장송곡\'으로 안개 마녀를 소환하면 (R)\'석화의 응시\'로 요릭을 기절시키거나 둔화시키며 대응하세요. 안개 마녀가 소환된 상태에서 요릭과 길게 싸우면 위험하니 (W)\'독기의 늪\'을 활용해 거리를 조절해야 해요. 마녀와 망령이 라인을 빠르게 밀 수 있으니 웨이브를 관리하며 정글의 지원을 요청하세요.', item: '내셔의 이빨을 첫 코어로 올려 공격 속도와 주문력을 확보하세요. 신발은 요릭의 기본 공격 피해를 줄이기 위해 판금 장화를 선택해요.', spell: '점멸과 점화를 추천해요. 요릭의 (Q)\'최후의 의식\'을 통한 체력 회복을 억제하여 킬각을 잡기에 좋아요.' },
    '우디르': { lv1: '우디르가 (Q)\'야생 발톱\' 태세로 다가오며 평타를 치면 체력이 빠르게 빠지니 거리를 유지하세요. (Q)\'맹독 폭발\'로 적을 중독시키면 이동 속도가 빨라지니 이를 이용해 우디르의 접근을 피하며 견제하세요. 1~2레벨 구간에는 무리하게 싸우지 말고 미니언을 챙기며 기회를 보세요.', lv3: '우디르가 (E)\'불길 쇄도\'로 돌진하여 기절을 시도할 때 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막는 것이 중요해요. 우디르가 (W)\'강철 갑옷\'을 사용하여 보호막과 회복을 얻었다면 그 효과가 끝난 뒤에 (E)\'쌍독니\'를 쏟아부으세요. 중독된 상태의 적에게 (E)\'쌍독니\'를 맞춰야 더 큰 피해를 입히고 체력을 회복할 수 있어요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\' 태세로 주변에 둔화를 걸며 다가오면 (R)\'석화의 응시\'를 사용하여 기절을 시켜야 해요. 우디르가 (E)\'불길 쇄도\'를 재사용하여 이동 불가 효과에 면역이 된 상태라면 무리하게 붙지 말고 거리를 벌리세요. 우디르가 폭풍을 풀어 적을 쫓아오기 전에 (W)\'독기의 늪\'과 (E)\'쌍독니\'로 빠르게 대응하며 라인을 관리하세요.', item: '첫 코어로 리안드리의 고통을 가서 우디르의 체력을 지속적으로 깎으세요. 신발은 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 우디르가 (W)\'강철 갑옷\'으로 체력을 회복할 때 점화를 사용하여 회복량을 줄이세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸며 다가오니 거리 조절이 중요해요. (Q)\'맹독 폭발\'을 우르곳의 이동 경로에 미리 깔아 중독시킨 뒤 (E)\'쌍독니\'로 짧게 딜교환하고 빠지세요. 평타에 (P)\'화염의 메아리\'가 붙어 있어 근접전은 피해야 해요.', lv3: '(E)\'경멸\' 돌진에 맞으면 뒤로 던져져 (W)\'심판의 원\' 사격에 노출되니 주의하세요. 우르곳이 들어오는 타이밍에 (W)\'독기의 늪\'을 깔면 (E)\'경멸\' 사용을 막을 수 있어요. (Q)\'맹독 폭발\'로 중독시킨 상태에서 (E)\'쌍독니\'를 계속 사용해 체력을 깎으세요.', lv6: '(R)\'불사의 공포\' 섬광탄에 맞은 뒤 체력이 낮아지면 처형당할 수 있으니 각별히 조심하세요. 우르곳이 (E)\'경멸\'로 진입할 때 정면에서 (R)\'석화의 응시\'를 사용하여 기절시키면 일방적인 딜교환이 가능해요. (Q)\'맹독 폭발\'의 이동 속도 증가 효과를 이용해 우르곳의 사거리 밖에서 무빙하세요.', item: '리안드리의 고통을 가서 체력이 높은 우르곳에게 지속적인 마법 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 순간이동을 추천해요. 라인 복귀를 빠르게 하고 순간이동 운영을 통해 다른 라인에 영향력을 행사하세요.' },
    '워윅': { lv1: '(Q)\'맹독 폭발\'을 활용해 멀리서 견제하며 워윅이 (Q)\'야수의 송곳니\'로 붙지 못하게 거리를 조절하세요. 워윅은 (Q)\'야수의 송곳니\'로 피해를 입히며 체력을 회복하니 초반에 너무 깊게 들어가지 않는 것이 중요해요. (Q)\'맹독 폭발\'을 맞혀 이동 속도를 높이며 거리를 유지하세요.', lv3: '(Q)\'맹독 폭발\'로 적을 중독시킨 뒤 (E)\'쌍독니\'를 맞춰 피해를 높이고 체력을 회복하세요. 워윅의 (E)\'원시의 포효\'가 켜진 동안은 받는 피해가 감소하고 끝나면 근처 적이 공포에 빠지니 사거리 밖으로 물러나 있다가 포효가 끝난 뒤 몰아치세요. 워윅이 (Q)\'야수의 송곳니\'로 도약하기 전에 발밑에 (W)\'독기의 늪\'을 깔면 이동 스킬 사용을 막을 수 있어요.', lv6: '워윅이 (R)\'무한의 구속\'으로 돌진하여 제압하면 정화로 풀 수 없으니 정면에서 맞지 않게 주의하세요. 워윅의 체력이 낮아지면 (W)\'피의 사냥\'으로 인해 매우 빠르게 접근하므로 (R)\'석화의 응시\'를 사용하여 접근을 차단해야 해요. 정글러가 근처에 있다면 워윅이 (R)\'무한의 구속\'을 사용하기 전에 라인을 관리하며 조심하세요.', item: '모렐로노미콘과 헤르메스의 발걸음을 추천해요. 모렐로노미콘의 상처로 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'의 회복을 줄이고, 헤르메스의 발걸음은 마법 저항력과 강인함을 줘요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 체력 회복 효과를 낮춰서 킬을 내기 쉽게 만드세요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 오며 체력을 회복해요. (Q)\'맹독 폭발\'로 적을 중독시키고 (E)\'쌍독니\'로 견제하며 거리를 유지하세요. 이렐리아가 (Q)\'칼날 쇄도\'를 사용할 수 있는 미니언 위치를 피해 서는 것이 중요해요.', lv3: '이렐리아의 (E)\'쌍검협무\'가 두 칼날이 만나는 지점에 맞으면 기절하니 그 길목을 피하세요. 이렐리아가 (W)\'저항의 춤\'을 사용해 피해 감소를 켜는 동안에는 (E)\'쌍독니\'로 무리하게 교환하지 마세요. (W)\'독기의 늪\'을 깔아 이렐리아가 (Q)\'칼날 쇄도\'로 이동하는 것을 방해하세요.', lv6: '이렐리아가 (R)\'선봉진격검\'으로 표식을 남기고 들어오면 (R)\'석화의 응시\'로 기절시켜 대응하세요. (W)\'독기의 늪\'을 사용하여 이렐리아가 (Q)\'칼날 쇄도\'를 연속해서 사용하지 못하도록 막는 것이 핵심이에요. 이렐리아의 진입을 막으며 라인을 안전하게 관리하세요.', item: '첫 코어 아이템으로 내셔의 이빨을 가서 주문력과 공격 속도를 얻으세요. 신발은 이렐리아의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 탈진을 추천해요. 탈진으로 이렐리아의 피해량을 감소시켜 (Q)\'칼날 쇄도\' 진입을 견뎌내세요.' },
    '일라오이': { lv1: '1~2레벨에는 (P)\'고대신의 예언자\' 촉수가 있는 벽 근처를 피해 라인 중앙에 서세요. (Q)\'맹독 폭발\'로 일라오이를 중독시키고 이동 속도를 높여 거리 조절을 하며 견제하세요. 일라오이가 다가오려 하면 뒤로 물러나며 일방적으로 피해를 입히세요.', lv3: '(E)\'영혼의 시험\'에 맞으면 영혼에서 너무 멀어지지 않도록 주의하며 (E)\'쌍독니\'로 계속 견제하세요. 일라오이가 (W)\'혹독한 가르침\'으로 도약하려 할 때 발밑에 (W)\'독기의 늪\'을 깔면 이동 스킬 사용을 막아 접근을 저지할 수 있어요. 상대의 핵심 기술인 영혼 분리가 빠진 시점을 노려 공격하세요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 쓰면 즉시 범위를 벗어나 소환된 촉수들의 공격을 피하세요. 일라오이가 정면으로 다가올 때 (R)\'석화의 응시\'로 기절시켜 공격 흐름을 끊고 거리를 벌리세요. 라인을 당겨서 정글러와 함께 일라오이를 압박하는 것이 편해요.', item: '리안드리의 고통과 판금 장화를 추천해요. 리안드리의 고통으로 체력이 높은 일라오이에게 지속 피해를 주고 판금 장화로 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 일라오이의 강력한 진입으로부터 벗어나고 라인 손실을 줄이기 위해 필요해요.' },
    '자크': { lv1: '1~2레벨에는 자크가 (Q)\'탄성 주먹\'으로 붙으려 할 때 (Q)\'맹독 폭발\'로 먼저 중독을 시키고 거리를 유지하세요. 자크가 (P)\'세포 분열\' 조각을 주우러 움직일 때 (E)\'쌍독니\'를 활용해 체력 차이를 벌리는 것이 중요해요.', lv3: '자크가 (E)\'새총 발사\'로 돌진할 때 (W)\'독기의 늪\'을 깔아두면 이동 스킬을 사용하지 못하게 차단할 수 있어요. (W)\'불안정 물질\'은 최대 체력 비례 피해라 붙으면 아프니 사거리 밖에서 (Q)\'맹독 폭발\'을 맞히세요. 이어서 (E)\'쌍독니\'로 딜교환을 하며 체력을 회복하세요.', lv6: '자크가 (R)\'바운스!\'를 사용해 다가올 때 (R)\'석화의 응시\'로 기절시켜 진입을 끊어내야 해요. 자크를 처치해도 (P)\'세포 분열\'로 조각이 하나라도 살아 있으면 부활하니 조각에 (Q)\'맹독 폭발\'을 던져 부활을 막으세요.', item: '첫 코어 아이템은 내셔의 이빨을 가고 신발은 헤르메스의 발걸음을 선택하세요. 자크의 마법 피해를 줄이고 (Q)\'탄성 주먹\'과 (R)\'바운스!\'의 둔화 시간을 줄이는 데 도움이 돼요.', spell: '점멸과 점화를 추천해요. 점화는 자크가 (P)\'세포 분열\'로 체력을 회복하는 것을 억제하기에 좋아요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 빠르게 공격하며 체력을 회복하니 무리한 평타 교환은 피하세요. (Q)\'맹독 폭발\'로 중독시킨 뒤 (E)\'쌍독니\'를 섞어 짧게 딜교환하고 거리를 유지하세요. 자헨이 (P)\'전쟁 단련\' 중첩을 쌓지 못하게 최대한 멀리서 견제해요.', lv3: '자헨이 (E)\'찬란한 쇄도\'나 (W)\'공포의 귀환\'으로 진입하려 할 때 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막으세요. (W)\'공포의 귀환\'에 끌려가지 않도록 주의하며, 중독된 적에게 (E)\'쌍독니\'를 계속 사용해 체력을 회복하세요. 자헨의 (Q)\'다르킨의 글레이브\' 재사용으로 인한 공중 띄우기 공격을 조심하며 거리 조절을 해요.', lv6: '자헨이 (R)\'단호한 판결\'로 날아올라 내려찍는 순간 (R)\'석화의 응시\'를 사용해 기절시키고 딜교환을 주도하세요. (P)\'전쟁 단련\'으로 부활할 수 있으니 체력이 낮아져도 방심하지 말고 확실하게 처치해야 해요. 라인 관리 중에 자헨이 진입하면 (W)\'독기의 늪\'으로 이동 스킬을 봉쇄하고 빠르게 거리를 벌리세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 자헨에게 지속 피해를 입히세요. 신발은 자헨의 기본 공격 피해를 줄여 주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 자헨은 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하므로 점화의 치유 감소 효과가 필요해요.' },
    '잭스': { lv1: '(Q)\'맹독 폭발\'을 사용하여 잭스를 중독시키고 이동 속도를 높여 거리를 유지하세요. 잭스가 (Q)\'도약 공격\'으로 빠르게 접근할 수 있으니 항상 사거리 밖에서 견제하며 조심하세요. 첫 웨이브부터 중독 상태를 유지하며 체력을 깎아두는 것이 중요해요.', lv3: '잭스가 (Q)\'도약 공격\'으로 진입하려는 타이밍에 (W)\'독기의 늪\'을 깔아 진입을 차단하세요. (E)\'반격\'은 기본 공격을 회피하고 광역 스킬 피해를 줄이니 이때는 평타 대신 (E)\'쌍독니\'로 공격하고 기절당하기 전에 범위 밖으로 벗어나세요. 잭스의 반격이 끝난 직후 중독된 상태의 적에게 (E)\'쌍독니\'를 빠르게 연사하여 체력을 회복하며 딜교환하세요.', lv6: '잭스가 (Q)\'도약 공격\'으로 거리를 좁히면 (R)\'석화의 응시\'를 사용하여 정면의 잭스를 기절시키세요. (R)\'무기의 달인\'으로 방어력과 마법 저항력이 오른 잭스를 상대로는 지속적으로 피해를 누적시키며 체력을 깎으세요. 정글러가 개입할 때 기절시킨 잭스를 대상으로 집중 공격하면 쉽게 처치할 수 있어요.', item: '리안드리의 고통을 가서 체력을 보완하고 지속적인 마법 피해를 입히세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화의 피해를 더해 잭스가 (Q)\'도약 공격\'으로 진입했을 때 빠르게 처치하세요.' },
    '제이스': { lv1: '제이스가 캐논 형태로 (Q)\'전격 폭발\'을 사용하여 멀리서 견제할 때 거리를 유지하며 미니언을 챙기세요. (Q)\'맹독 폭발\'을 맞춰 제이스가 근접하지 못하게 독을 묻히는 것이 중요해요. 제이스가 해머 형태로 (Q)\'하늘로!\'를 사용하며 들어오면 대상 지정 도약이라 미니언으로 막을 수 없으니 바로 거리를 벌리세요.', lv3: '제이스가 (Q)\'하늘로!\'로 도약해 들어오려 할 때 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막으세요. (E)\'천둥 강타\'는 해머 형태에서 밀쳐내는 스킬이니 밀려난 뒤 거리가 벌어지는 것을 감안해 위치를 잡으세요. (Q)\'맹독 폭발\'로 중독시킨 뒤 (E)\'쌍독니\'를 사용하면 큰 피해를 입힐 수 있어요.', lv6: '제이스가 (R)\'머큐리 캐논\'으로 변환하여 방어력을 깎으려 할 때 (R)\'석화의 응시\'를 사용하여 행동을 제약하세요. 제이스가 (Q)\'하늘로!\'로 들어오는 타이밍에 (W)\'독기의 늪\'을 깔아두면 이동 스킬을 쓰지 못해 킬각을 잡기 쉬워요. 제이스가 형태를 바꾸는 틈을 타 (E)\'쌍독니\'를 집중적으로 사용하세요.', item: '첫 코어로 내셔의 이빨을 선택해 지속적인 공격력을 확보하세요. 신발은 제이스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점멸로 (R)\'석화의 응시\' 각을 만들고 점화의 지속 고정 피해로 마무리하세요.' },
    '초가스': { lv1: '초가스의 (Q)\'파열\'은 지면 표시가 보인 후 적을 공중에 띄우니, 표시가 보이면 즉시 범위 밖으로 이동하세요. (Q)\'맹독 폭발\'로 견제하며 챔피언 적중 시 얻는 이동 속도를 이용해 거리를 조절하세요. 초가스가 (E)\'날카로운 가시\'를 쓰며 다가올 때는 평타 교환을 피하고 사거리 밖에서 공격하세요.', lv3: '(W)\'흉포한 울부짖음\'에 침묵되면 (E)\'쌍독니\'를 쓸 수 없으니, 초가스가 비명을 지르는 범위 밖에서 싸우세요. (Q)\'파열\'을 피한 직후 (W)\'독기의 늪\'을 깔면 초가스의 접근을 늦추고 지속적인 피해를 줄 수 있어요. 침묵 스킬이 빠진 틈을 타 (Q)\'맹독 폭발\'을 맞히고 (E)\'쌍독니\'로 빠르게 체력을 회복하며 딜교환하세요.', lv6: '(R)\'포식\'은 방어력을 무시하는 큰 고정 피해를 입히니, 체력이 낮을 때는 초가스와 너무 가까이 붙지 마세요. 초가스가 진입할 때 (R)\'석화의 응시\'로 기절시켜 공격 흐름을 끊고 거리를 벌리세요. (W)\'독기의 늪\'으로 정글러의 진입 경로를 차단하고 (Q)\'맹독 폭발\'로 지속적인 압박을 가하며 라인을 관리하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력이 많은 초가스에게 지속적인 피해를 입히세요. 신발은 마법 저항력을 제공하고 (E)\'날카로운 가시\'의 둔화 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'육식\'을 통한 초가스의 체력 회복 효과를 감소시키세요.' },
    '카밀': { lv1: '(Q)\'맹독 폭발\'을 사용해 카밀을 중독시키고 이동 속도를 높여 거리를 유지하세요. 카밀이 (Q)\'정확성 프로토콜\'로 빠르게 접근해 평타를 칠 때 (P)\'적응형 방어 체계\' 보호막이 생기니 무리한 평타 교환은 피하세요. 거리 조절을 하며 (Q)\'맹독 폭발\'로 지속적인 피해를 누적하세요.', lv3: '카밀이 (E)\'갈고리 발사\'로 진입하려 할 때 (W)\'독기의 늪\'을 발밑에 깔아 도약하지 못하게 막으세요. (W)\'전술적 휩쓸기\'의 바깥쪽 절반에 맞으면 둔화되고 카밀이 회복하니 최대한 안쪽으로 붙거나 완전히 벗어나세요. 카밀의 진입 스킬이 빠진 뒤 중독된 대상에게 (E)\'쌍독니\'를 빠르게 연사해 체력을 회복하며 압박하세요.', lv6: '(R)\'마법공학 최후통첩\'으로 갇히기 전에 접근하는 카밀을 (R)\'석화의 응시\'로 기절시켜 진입 흐름을 끊으세요. 만약 갇혔다면 당황하지 말고 지역 안에서 (Q)\'맹독 폭발\'과 (E)\'쌍독니\'로 맞서 피해를 교환하세요. 라인을 밀어 넣고 벽 근처에서 (E)\'갈고리 발사\'에 노출되지 않도록 주의하며 정글러의 개입을 경계하세요.', item: '리안드리의 고통을 첫 코어로 선택해 지속 피해를 입히세요. 신발은 카밀의 주력인 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 카밀이 (W)\'전술적 휩쓸기\'로 회복하는 것을 점화의 치유 감소 효과로 억제하세요.' },
    '카사딘': { lv1: '(Q)\'맹독 폭발\'을 사용하여 상대의 (Q)\'무의 구체\' 사거리 밖에서 지속적으로 독을 묻히며 견제하세요. 초반에는 상대가 (Q)\'무의 구체\'로 보호막을 얻으며 버티는 구간이므로 무리한 진입보다는 거리를 유지하며 독을 쌓는 것이 좋아요.', lv3: '카사딘의 (P)\'공허석\'은 받는 마법 피해를 줄이고 (Q)\'무의 구체\'는 마법 피해를 흡수하는 보호막을 주니 보호막이 있는 동안은 (E)\'쌍독니\'를 아끼세요. (W)\'독기의 늪\'으로 둔화시켜 접근을 방해하고 먼저 (Q)\'맹독 폭발\'로 독을 묻히세요. 보호막이 사라진 뒤 중독된 대상에게 (E)\'쌍독니\'를 빠르게 사용해 체력을 회복하세요.', lv6: '상대가 (R)\'균열 이동\'을 사용하여 갑자기 접근할 때 (R)\'석화의 응시\'를 정면으로 맞춰 기절시키고 공격하세요. (W)\'독기의 늪\'을 사용해 상대의 이동 스킬 사용을 막으며 라인을 관리하고 정글러의 개입을 유도하는 것이 좋아요.', item: '헤르메스의 발걸음과 대천사의 지팡이를 선택하세요. 헤르메스의 발걸음으로 카사딘의 마법 피해에 대비하고, 대천사의 지팡이로 마나와 주문력을 확보해 (E)\'쌍독니\' 연사를 이어 가요.', spell: '점멸과 점화를 추천해요. 점멸로 (R)\'석화의 응시\' 각을 만들고 점화의 지속 고정 피해로 마무리해요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'이 처음 적중한 대상에게만 피해를 주므로 미니언 뒤에 숨어 표식을 피하세요. (Q)\'맹독 폭발\'로 적을 중독시켜 이동 속도를 얻으며 적절한 거리를 유지하세요. (P)\'폭풍의 표식\'이 세 번 쌓이면 기절하니 맞은 횟수를 세며 주의하세요.', lv3: '(E)\'번개 질주\'로 빠르게 접근하는 케넨에게 (W)\'독기의 늪\'을 사용해 이동 속도를 늦추세요. 중독된 상태의 케넨에게 (E)\'쌍독니\'를 연사해 피해를 입히고 자신의 체력을 회복하세요. (W)\'전류 방출\'로 표식이 빠르게 쌓일 수 있으니 거리를 두며 짧게 교환하세요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 켜고 진입하면 (R)\'석화의 응시\'로 정면의 적을 기절시켜 흐름을 끊으세요. 궁극기 사용 중인 케넨은 마법 저항력이 상승하니 한 번에 잡으려 하기보다 천천히 체력을 깎으세요. 정글 갱킹 상황에서 (P)\'폭풍의 표식\'에 기절하면 스킬을 못 쓰니 항상 거리를 유지하세요.', item: '리안드리의 고통과 헤르메스의 발걸음을 추천해요. 체력을 보충하고 지속 피해를 입히며 강인함으로 기절 시간을 줄일 수 있어요.', spell: '점멸과 정화를 추천해요. (P)\'폭풍의 표식\'으로 기절했을 때 정화로 빠르게 풀고 대응하세요.' },
    '케일': { lv1: '1~2레벨 구간인 케일은 (P)\'거룩한 승천\' 효과가 낮은 초반이 가장 약한 구간이에요. (Q)\'맹독 폭발\'로 먼저 독을 묻히고 거리를 조절하며 압박하세요. 케일의 (Q)\'광휘의 일격\'은 처음 맞은 대상에게 멈추는 투사체이니 무빙으로 피해야 해요.', lv3: '3레벨 이후 (Q)\'맹독 폭발\'로 중독시킨 뒤 (E)\'쌍독니\'를 사용해 체력을 회복하며 딜교환을 하세요. 케일이 (E)\'화염주문검\'을 사용하면 사거리가 늘어나고 잃은 체력에 비례한 추가 피해를 주니 조심해야 해요. 케일이 (W)\'천상의 축복\'으로 체력을 회복하고 이동 속도를 얻어 빠지려 할 때 (W)\'독기의 늪\'을 깔아 둔화시키세요.', lv6: '6레벨 이후 케일이 (R)\'신성한 심판\'을 사용하면 대상이 무적이 되므로 딜이 들어가지 않는 점을 주의하세요. 무적 상태가 해제되는 타이밍에 맞춰 (R)\'석화의 응시\'로 기절을 시킨 뒤 (E)\'쌍독니\'로 몰아붙여야 해요. 케일의 사거리가 점점 늘어나니 정글러를 호출해 초반에 이득을 보는 것이 좋아요.', item: '헤르메스의 발걸음을 먼저 올려 마법 저항력과 강인함을 챙기세요. 첫 코어 아이템은 리안드리의 고통을 선택해 지속적인 마법 피해를 입히는 것이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 케일의 (W)\'천상의 축복\' 회복 효과를 감소시키며 킬을 노려보세요.' },
    '코그모': { lv1: '코그모의 (W)\'생체마법 폭격\'으로 인해 사거리가 늘어날 수 있으니 무리하게 접근하지 마세요. (Q)\'맹독 폭발\'을 적중시켜 이동 속도를 얻으며 적절한 거리에서 견제하세요. (Q)\'부식성 침\'에 맞아 마법 저항력이 낮아지는 것을 조심하며 대응하세요.', lv3: '(Q)\'맹독 폭발\'로 먼저 적을 중독시킨 뒤 (E)\'쌍독니\'를 사용하여 큰 피해를 입히고 체력을 회복하세요. 코그모의 (Q)\'부식성 침\'을 피하면서 (E)\'공허의 분비물\'이 남긴 흔적을 조심하며 위치를 잡으세요. (W)\'독기의 늪\'을 깔아 코그모를 둔화시키며 딜교환을 진행하세요.', lv6: '(R)\'석화의 응시\'로 코그모를 기절시킨 후에 (E)\'쌍독니\'를 빠르게 사용하여 킬을 노려보세요. 코그모의 (R)\'살아있는 곡사포\'는 체력이 낮은 적에게 큰 피해를 주니 조심해야 해요. 라인을 빠르게 밀어넣고 정글러의 개입에 대비하며 플레이하세요.', item: '헤르메스의 발걸음과 리안드리의 고통을 가세요. 코그모의 마법 피해에 대응하고 지속적인 피해를 입히기 위해서예요.', spell: '점멸과 점화예요. 점멸로 거리를 좁히고 점화의 고정 피해로 적을 빠르게 마무리하기 위해서예요.' },
    '코르키': { lv1: '(Q)\'인광탄\'은 위치 지정 스킬이라 미니언 뒤에 숨어도 소용없으니 폭탄이 떨어질 지점 밖으로 움직이세요. (Q)\'맹독 폭발\'을 사용해 적을 중독시키고 이동 속도를 높여 거리 조절을 하며 견제하세요. 무리하게 다가가기보다 체력을 보존하며 성장에 집중해요.', lv3: '상대가 (W)\'발키리\'로 진입하거나 도망치려 할 때 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 차단하세요. 늪에 빠져 둔화된 상태의 적에게 (E)\'쌍독니\'를 빠르게 연사하여 피해를 입히고 체력을 회복하세요. 상대의 (E)\'개틀링 건\'에 맞으면 마법 저항력이 낮아지니 주의하며 거리를 유지해요.', lv6: '(R)\'석화의 응시\'로 상대를 기절시킨 뒤 (E)\'쌍독니\'를 연사해 빠르게 처치하세요. 상대의 (R)\'미사일 폭격\'은 사거리가 매우 길어 체력이 낮을 때 갑작스럽게 맞지 않도록 주의해요. 라인을 적절히 관리하며 정글러의 개입을 기다리거나 함께 공격하세요.', item: '판금 장화와 리안드리의 고통을 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 리안드리의 고통은 체력을 보충하며 지속적인 마법 피해를 입히기에 좋아요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀와 합류를 돕고 점멸로 (R)\'석화의 응시\' 각을 만들어 변수를 창출하세요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식을 활용한 기본 공격 견제가 매우 강해요. (Q)\'맹독 폭발\'을 적중시켜 얻는 이동 속도 증가 효과로 거리 조절을 하며 퀸의 평타 사거리를 관리하세요. 표식이 남은 상태에서 평타 교환을 하면 피해를 많이 입으니 주의하세요.', lv3: '퀸이 (E)\'공중제비\'로 진입하려는 경로에 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막으세요. 퀸이 늪에 빠져 (E)\'공중제비\'를 쓰지 못할 때 (E)\'쌍독니\'를 빠르게 연사해 피해를 입히고 체력을 회복하세요. (Q)\'실명 공격\'에 맞으면 시야가 좁아지니 발러가 날아오는 방향을 보고 맞기 전에 피하세요.', lv6: '퀸이 (R)\'후방 지원\'으로 빠르게 날아와 강습하는 타이밍에 (R)\'석화의 응시\'를 사용하여 정면의 퀸을 기절시키세요. 기절한 퀸은 (E)\'공중제비\'로 도망갈 수 없으므로 빠르게 공격해 킬각을 잡으세요. 퀸이 로밍을 다니며 자리를 비우면 빠르게 라인을 밀어 포탑에 피해를 입히세요.', item: '판금 장화를 선택해 퀸의 기본 공격 피해를 줄이세요. 리안드리의 고통을 첫 코어로 선택해 체력을 보충하고 스킬 공격으로 적을 불태워 지속 피해를 입히세요.', spell: '점멸과 순간이동을 추천해요. 퀸의 빠른 로밍에 대응해 라인 손실을 줄이고 빠르게 복귀하세요.' },
    '크산테': { lv1: '크산테는 (Q)\'엔토포 타격\'으로 둔화를 걸고 적중시켜 끌어당기려 해요. (Q)\'맹독 폭발\'을 사용해 상대에게 독을 묻히고 이동 속도를 높여 거리 조절을 하세요. 첫 웨이브부터 계속 견제하며 크산테가 쉽게 다가오지 못하게 하세요.', lv3: '크산테가 (E)\'발놀림\'으로 진입하기 전에 발밑에 (W)\'독기의 늪\'을 깔아 돌진을 쓰지 못하게 하세요. (W)\'길을 여는 자\'는 충전 중 저지 불가 상태라 군중 제어로 끊을 수 없으니 충전 동작이 보이면 돌진 경로에서 즉시 벗어나세요. 상대의 돌진기가 빠진 타이밍에 (E)\'쌍독니\'를 계속해서 사용해 체력을 깎으세요.', lv6: '크산테가 (R)\'총공세\'로 벽 너머로 밀어내려 하면 (R)\'석화의 응시\'를 사용해 정면의 적을 기절시키고 거리를 벌리세요. 총공세 상태의 크산테는 최대 체력과 추가 마법 저항력이 감소하니 이때 (E)\'쌍독니\'로 강력한 피해를 입히는 것이 좋아요. 정글러의 개입이 예상되는 벽 근처에서는 가급적 떨어져서 라인을 관리하세요.', item: '리안드리의 고통과 판금 장화를 추천해요. 리안드리의 고통으로 체력이 많은 크산테에게 지속 피해를 입히고, 판금 장화로 상대의 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 크산테의 돌진기에서 벗어나기 위해 점멸이 필요하며, 순간이동으로 라인 손실을 방지하세요.' },
    '클레드': { lv1: '1~2레벨에는 (Q)\'맹독 폭발\'로 클레드를 중독시켜 체력을 깎으며 거리를 유지하세요. 클레드가 (Q)\'덫날리기\'를 던졌을 때 덫에 붙잡힌 채 근처에 머물면 끌려가며 추가 피해를 입으니 즉시 거리를 벌리세요. 스칼의 체력을 먼저 깎아 클레드를 내리게 만드는 것이 중요해요.', lv3: '클레드가 (E)\'이랴!\'로 돌진해 들어올 때 발밑에 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막고 둔화를 거세요. (W)\'버럭버럭\'이 켜져 공격 속도가 빨라진 클레드와는 평타 싸움을 피하고, 중독된 상태에서 (E)\'쌍독니\'를 계속 사용해 체력을 회복하며 딜교환하세요. 클레드가 돌진 후 다시 돌아오는 타이밍을 피해 거리 조절을 하는 것이 핵심이에요.', lv6: '(R)\'돌겨어어억!!!\'으로 돌진해 보호막을 얻고 들어와 자신을 뒤로 밀어내려는 클레드를 (R)\'석화의 응시\'로 기절시켜 흐름을 끊으세요. 클레드가 스칼에서 내려 챔피언 피해량이 줄어든 상태라면 (E)\'쌍독니\'로 빠르게 공격해 스칼을 다시 타지 못하게 처치하세요. 라인을 당겨 유지하며 적 정글러의 개입에 대비하는 것이 좋아요.', item: '리안드리의 고통을 첫 코어로 선택해 스칼과 클레드에게 지속적인 마법 피해를 입히세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 스칼에서 내린 클레드를 점화의 지속 고정 피해로 마무리해 스칼을 다시 타지 못하게 하세요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 (P)\'절대 미각\' 중첩을 쌓으며 견제해요. (Q)\'혀 채찍\'은 처음 맞는 유닛에게 적중하니 미니언 뒤에 숨어서 피해를 줄이세요. (Q)\'맹독 폭발\'로 적을 중독시킨 상태에서만 (E)\'쌍독니\'를 사용하여 체력을 회복해야 해요.', lv3: '(Q)\'맹독 폭발\'로 독을 묻힌 뒤 (E)\'쌍독니\'를 맞춰 딜교환을 진행하세요. 탐 켄치가 (W)\'심연 잠수\'를 사용하면 범위 밖으로 피해야 해요. (Q)\'혀 채찍\'의 사거리를 의식하며 (P)\'절대 미각\' 중첩이 쌓이지 않도록 거리를 조절하세요.', lv6: '(P)\'절대 미각\' 중첩이 많을 때는 (R)\'집어삼키기\'에 먹히지 않도록 조심하세요. 탐 켄치가 (E)\'두꺼운 피부\'를 사용해 보호막을 만들면 그 효과가 사라진 뒤에 공격을 쏟아부으세요. (R)\'석화의 응시\'로 상대를 기절시킨 뒤 (E)\'쌍독니\'로 마무리하세요.', item: '리안드리의 고통을 첫 코어로 가서 체력이 높은 탐 켄치에게 지속 피해를 입히세요. 신발은 탐 켄치의 마법 피해와 (Q)\'혀 채찍\' 기절 지속시간을 줄여 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치가 (Q)\'혀 채찍\'과 (E)\'두꺼운 피부\'로 회복하는 양을 줄이세요.' },
    '트런들': { lv1: '(Q)\'맹독 폭발\'로 먼저 독을 묻히고 (E)\'쌍독니\'로 견제하며 거리를 유지하세요. 트런들이 (Q)\'깨물기\'로 접근해 공격력을 흡수하면 맞붙지 말고 빠르게 거리를 벌려야 해요. 트런들은 (P)\'헌납\' 덕분에 미니언이 쓰러질 때 체력을 회복하니 근처에서 싸우는 것을 피하세요.', lv3: '트런들이 (W)\'얼음 왕국\' 안에 있을 때는 공격 속도와 회복량이 늘어나니 영역 밖으로 물러나 (Q)\'맹독 폭발\'로 견제하세요. (E)\'얼음 기둥\'은 지나갈 수 없는 벽이니 기둥 위치를 보고 갇히지 않게 서고 (W)\'독기의 늪\'으로 트런들의 접근을 늦추세요. (Q)\'맹독 폭발\'로 독을 묻힌 뒤 (E)\'쌍독니\'를 연사하며 거리를 조절하세요.', lv6: '트런들이 (R)\'진압\'을 사용해 방어력과 마법 저항력을 훔치면 매우 아프니 (R)\'석화의 응시\'로 기절시켜 대응하세요. (R)\'석화의 응시\'를 맞춘 뒤 (E)\'쌍독니\'를 쏟아부어 킬각을 노리는 것이 좋아요. 트런들은 기둥을 활용해 도주로를 차단할 수 있으니 라인을 밀어 넣고 정글러의 도움을 요청하며 조심스럽게 움직이세요.', item: '내셔의 이빨을 첫 코어로 선택해 주문력과 공격 속도를 함께 챙기세요. 신발은 트런들의 기본 공격 피해를 줄여주는 판금 장화가 적합해요.', spell: '점멸과 점화를 추천해요. 점화로 트런들이 (P)\'헌납\'이나 (W)\'얼음 왕국\'을 통해 회복하는 효과를 줄여 마무리하세요.' },
    '트린다미어': { lv1: '(Q)\'맹독 폭발\'로 적을 중독시킨 뒤 (E)\'쌍독니\'를 사용해 체력을 회복하며 짧게 딜교환하세요. 트린다미어는 (P)\'격노\'로 분노를 쌓아 치명타 확률을 높이니 평타 거리를 내주지 않는 것이 중요해요. 첫 웨이브부터 무리하게 붙지 말고 사거리를 유지하며 체력을 보존하세요.', lv3: '트린다미어가 (E)\'회전 베기\'로 진입하려는 경로에 (W)\'독기의 늪\'을 정확히 깔아 이동 스킬 사용을 막고 둔화시키세요. (W)\'조롱의 외침\'을 맞은 상태에서 등을 돌려 도망치면 둔화 효과가 적용되니 정면을 유지하며 거리를 조절하세요. 중독된 적에게 (E)\'쌍독니\'를 연사해 피해를 주고 체력을 회복하며 압박하세요.', lv6: '(R)\'불사의 분노\'가 켜진 동안에는 죽지 않으므로 (R)\'석화의 응시\'로 기절시켜 시간을 벌며 안전하게 거리를 벌리세요. 궁극기 지속시간이 끝나는 순간에 맞춰 (E)\'쌍독니\'를 연사하면 처치할 수 있어요. 트린다미어가 (Q)\'피의 갈망\'으로 체력을 회복하기 전에 빠르게 피해를 입히고 정글러를 부르세요.', item: '라일라이의 수정홀을 첫 코어로 가서 스킬로 적을 둔화시켜 거리를 유지하세요. 신발은 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 트린다미어는 (Q)\'피의 갈망\'으로 체력을 회복하므로 점화의 치유 감소 효과가 유용해요.' },
    '티모': { lv1: '(Q)\'맹독 폭발\'을 사용하여 티모를 중독시키고 (E)\'쌍독니\'로 피해를 입히며 거리를 유지하세요. 티모가 수풀 속에서 (P)\'유격 전투\'로 투명해져서 기습할 수 있으니 수풀 근처에서는 주의를 기울여야 해요. (Q)\'실명 다트\'에 맞지 않도록 적절한 거리를 유지하며 대응하세요.', lv3: '티모의 (Q)\'실명 다트\'가 빠진 타이밍에 (Q)\'맹독 폭발\'로 중독을 시킨 뒤 (E)\'쌍독니\'를 사용하여 딜교환을 하세요. 티모가 (W)\'신속한 이동\'을 사용하여 거리를 벌리려 하면 (W)\'독기의 늪\'을 깔아 둔화 효과를 활용하세요. 티모가 (Q)\'실명 다트\'를 사용하기 전에 (Q)\'맹독 폭발\'로 먼저 견제하는 것이 좋아요.', lv6: '(R)\'석화의 응시\'로 티모를 기절시킨 뒤 (E)\'쌍독니\'를 연속으로 사용하여 킬을 노려보세요. 티모가 깔아둔 (R)\'유독성 함정\'을 밟으면 이동 속도가 느려지고 피해를 입으니 버섯의 위치를 잘 확인하며 이동하세요. 티모가 (R)\'유독성 함정\'을 설치하러 갈 수 있으니 라인 관리에도 신경 써야 해요.', item: '내셔의 이빨을 첫 코어로 가서 주문력과 공격 속도를 챙기고 기본 공격에 추가 마법 피해를 더하세요. 신발은 티모의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 티모가 (Q)\'실명 다트\'를 쓰고 거리를 벌리며 버티려 할 때 점화로 마무리 피해를 입히세요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'으로 압박할 수 있으니 거리를 유지하며 (Q)\'맹독 폭발\'로 견제하세요. (P)\'필멸자의 의지\'가 쌓여 강화된 기술이 나오기 전에는 짧게 교환하고 물러나세요.', lv3: '판테온이 (W)\'방호의 도약\'으로 진입할 때 (W)\'독기의 늪\'을 깔아 이동 스킬 사용을 막는 것이 중요해요. (E)\'방패 돌격\'을 켠 판테온의 정면에서는 (E)\'쌍독니\' 피해가 막힐 수 있으니 스킬이 끝난 뒤에 공격하세요. (Q)\'맹독 폭발\'로 중독시킨 뒤 (E)\'쌍독니\'를 사용해야 피해를 높이고 체력을 회복할 수 있어요.', lv6: '판테온이 (R)\'거대 유성\'을 사용해 날아오면 착지 지점을 확인하고 미리 피하세요. (W)\'방호의 도약\'이 빠진 순간에 (R)\'석화의 응시\'를 적중시키면 킬을 노리기 수월해요. 판테온이 궁극기로 다른 라인에 합류한다면 빠르게 라인을 정리하며 이득을 챙기세요.', item: '공격 속도와 주문력을 위해 내셔의 이빨을 첫 코어로 가세요. 신발은 판테온의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 정화를 추천해요. (W)\'방호의 도약\' 기절을 정화로 빠르게 풀고 반격하세요.' },
    '피들스틱': { lv1: '(Q)\'맹독 폭발\'을 사용해 적을 중독시키고 이동 속도를 높여 거리를 유지하세요. 피들스틱이 시야 밖에서 (Q)\'공포\'를 사용해 기습하는 것을 경계하며 첫 웨이브를 받아내야 해요.', lv3: '(Q)\'맹독 폭발\'로 중독시킨 적에게 (E)\'쌍독니\'를 계속 사용해 피해를 입히고 체력을 회복하세요. (E)\'수확\'의 중심부에 맞으면 침묵에 걸려 스킬을 쓸 수 없으니 옆으로 피하는 것이 중요해요. (W)\'독기의 늪\'을 깔아 상대의 접근을 늦추며 거리 조절을 하세요.', lv6: '피들스틱이 (R)\'까마귀 폭풍\'으로 진입하는 순간 (R)\'석화의 응시\'를 사용해 정면에서 기절시키세요. 상대가 시야 밖에서 기습할 수 있으니 와드로 위치를 계속 확인하며 라인을 관리해야 해요. 기절시킨 후 (E)\'쌍독니\'로 빠르게 딜교환을 마무리하세요.', item: '헤르메스의 발걸음과 리안드리의 고통을 추천해요. 마법 저항력과 강인함으로 군중 제어 시간을 줄이고 지속적인 마법 피해를 입히기 위해서예요.', spell: '점멸과 정화를 추천해요. (Q)\'공포\'나 (E)\'수확\'의 침묵 같은 군중 제어 효과를 빠르게 풀고 거리를 벌려 생존하기 위해서예요.' },
    '피오라': { lv1: '피오라는 (Q)\'찌르기\'로 빠르게 접근해 (P)\'치명적인 검무\'의 급소를 공격하며 회복을 노려요. (Q)\'맹독 폭발\'로 먼저 독을 묻혀 이동 속도를 높이고 거리를 벌리며 견제하세요. 급소가 드러난 방향으로 서지 않도록 계속 움직이며 피오라의 진입 타이밍을 늦춰야 해요.', lv3: '피오라가 (W)\'응수\'를 사용하면 공격과 이동 불가 효과를 막아내니, 이 스킬이 빠지기 전까지는 (W)\'독기의 늪\'을 아끼세요. (W)\'응수\'가 끝난 뒤 (W)\'독기의 늪\'을 깔면 피오라의 (Q)\'찌르기\' 돌진을 막을 수 있어요. 독에 중독된 상태에서 (E)\'쌍독니\'를 빠르게 연사해 체력을 회복하며 딜교환을 하세요.', lv6: '피오라가 (R)\'대결투\'로 급소를 많이 드러내고 빠르게 다가오면 (R)\'석화의 응시\'로 기절시켜 흐름을 끊으세요. 다만 (W)\'응수\'에 (R)\'석화의 응시\'가 막히면 기절당해 위험하니 반드시 (W)\'응수\'가 빠진 것을 확인하고 사용하세요. (W)\'응수\'가 빠진 뒤에는 (W)\'독기의 늪\'으로 (Q)\'찌르기\' 진입을 막고 정글러가 올 때까지 라인을 당겨서 유지하세요.', item: '리안드리의 고통을 첫 코어로 선택해 체력을 보충하고 지속적인 마법 피해를 입히세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 피오라가 (P)\'치명적인 검무\'와 (R)\'대결투\'로 회복하는 양이 많으므로 점화의 치유 감소 효과가 필요해요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인을 압박하며 포탑 주변에서 이동 속도를 얻어요. 포탑 사거리 안으로 무리하게 들어가지 않도록 (Q)\'맹독 폭발\'로 독을 묻혀 이동 속도를 얻으며 거리를 조절하세요. 포탑이 설치되는 타이밍에 맞춰서 짧게 견제하며 미니언을 챙기는 것이 좋아요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'의 기절 범위를 피해 옆으로 무빙하며 하이머딩거의 위치를 확인하세요. 하이머딩거가 (W)\'마법공학 초소형 로켓\'을 쏘기 위해 조준할 때 (W)\'독기의 늪\'을 사용해 움직임을 방해하며 진입하세요. 독이 묻은 적에게 (E)\'쌍독니\'를 사용하면 강력한 피해를 입히고 체력을 회복할 수 있어요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'를 사용해 강화된 스킬을 쓰려 할 때 (R)\'석화의 응시\'로 정면에서 기절시키세요. 포탑이 깔린 곳으로 깊숙이 들어가는 것은 위험하니 라인을 당겨 관리하며 정글러의 개입을 요청하세요. (R)\'석화의 응시\' 이후 독이 묻은 적에게 스킬을 쏟아부어 빠르게 처치하세요.', item: '내셔의 이빨을 첫 코어로 선택해 공격 속도와 주문력을 확보하세요. 신발은 하이머딩거의 마법 피해와 (E)\'CH-2 전자폭풍 수류탄\'의 군중 제어 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 하이머딩거가 포탑을 깔고 거리를 벌릴 때 점멸로 접근해 점화로 마무리하기 좋아요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_cassiopeia);
if (typeof module !== 'undefined') module.exports = top_cassiopeia;
